_CHECKPOINT_SOURCE_LOCK = ".checkpoint-source.lock"
_CHECKPOINT_SOURCE_STAGE = ".checkpoint-source-stage.sqlite3"
_CHECKPOINT_SOURCE_LATEST = ".checkpoint-source-latest.sqlite3"
_CHECKPOINT_SOURCE_CLAIMED = ".checkpoint-source-claimed.sqlite3"
_TAKEOVER_UNSEAL_MARKER = ".takeover-unseal.json"
_CHECKPOINT_SOURCE_CLAIM_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]*$")
_CHECKPOINT_SOURCE_TRANSIENT_SQLITE_BASE_CODES = frozenset(
    {
        sqlite3.SQLITE_BUSY,
        sqlite3.SQLITE_LOCKED,
        sqlite3.SQLITE_READONLY,
        sqlite3.SQLITE_IOERR,
        sqlite3.SQLITE_FULL,
        sqlite3.SQLITE_CANTOPEN,
    }
)
_CHECKPOINT_SOURCE_TRANSIENT_OS_ERRNOS = frozenset(
    value
    for value in (
        errno.EACCES,
        errno.EAGAIN,
        errno.EBUSY,
        getattr(errno, "EDQUOT", None),
        errno.EINTR,
        errno.EIO,
        errno.EMFILE,
        errno.ENFILE,
        errno.ENOMEM,
        errno.ENOSPC,
        errno.EPERM,
        errno.EROFS,
        getattr(errno, "ETIMEDOUT", None),
    )
    if isinstance(value, int)
)
_CHECKPOINT_SOURCE_TRANSIENT_WINERRORS = frozenset(
    {
        5,  # ERROR_ACCESS_DENIED
        32,  # ERROR_SHARING_VIOLATION
        33,  # ERROR_LOCK_VIOLATION
        112,  # ERROR_DISK_FULL
        1450,  # ERROR_NO_SYSTEM_RESOURCES
        1455,  # ERROR_COMMITMENT_LIMIT
    }
)
_CHECKPOINT_SOURCE_PATH_RACE_ERRNOS = frozenset(
    {
        errno.ENOENT,
        errno.EEXIST,
        errno.ELOOP,
        errno.ENOTDIR,
        errno.EISDIR,
    }
)


def _checkpoint_source_failure_is_transient_unavailable(error: BaseException) -> bool:
    if isinstance(error, OSError):
        return error.errno in _CHECKPOINT_SOURCE_TRANSIENT_OS_ERRNOS or getattr(
            error, "winerror", None
        ) in _CHECKPOINT_SOURCE_TRANSIENT_WINERRORS
    if not isinstance(error, sqlite3.OperationalError):
        return False
    error_code = getattr(error, "sqlite_errorcode", None)
    return (
        isinstance(error_code, int)
        and (error_code & 0xFF) in _CHECKPOINT_SOURCE_TRANSIENT_SQLITE_BASE_CODES
    )


def _checkpoint_source_path_race(
    error: OSError,
    *,
    message: str,
) -> CheckpointSourceError | None:
    if error.errno not in _CHECKPOINT_SOURCE_PATH_RACE_ERRNOS:
        return None
    return CheckpointSourceError("checkpoint_source_path_unsafe", message)


class WorkspaceStoreError(RuntimeError):
    """Base error for the workspace persistence boundary."""


class WorkspaceAlreadyInitializedError(WorkspaceStoreError):
    pass


class WorkspaceNotInitializedError(WorkspaceStoreError):
    pass


class WorkspaceIntegrityError(WorkspaceStoreError):
    pass


class OwnerContentIndexUnavailableError(WorkspaceStoreError):
    """Indexed discovery requires an explicitly introduced, authenticated index."""


class CommittedCommandAcknowledgementError(WorkspaceStoreError):
    """A command committed before its local acknowledgement path failed."""

    def __init__(
        self,
        message: str,
        *,
        outcome: "CommandOutcome",
        cause: Exception,
    ) -> None:
        super().__init__(message)
        self.code = "committed_command_acknowledgement_failed"
        self.outcome = outcome
        self.original_error = cause


class CheckpointSourceError(WorkspaceStoreError):
    """Stable operational failure from the bounded checkpoint-source owner."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


class CheckpointSourceReacquisitionError(CheckpointSourceError):
    """A checkpoint-source handoff failed to establish its successor writer."""

    def __init__(
        self,
        message: str,
        *,
        capture_failure_code: str | None,
        published_source: "WorkspaceCheckpointSource | None",
    ) -> None:
        super().__init__("checkpoint_source_reacquisition_failed", message)
        self.capture_failure_code = capture_failure_code
        self.published_source = published_source


class CheckpointSourceOperationTeardownError(CheckpointSourceError):
    """Source-operation teardown failed and no active writer could be re-proven."""

    def __init__(
        self,
        message: str,
        *,
        published_source: "WorkspaceCheckpointSource | None",
    ) -> None:
        super().__init__("checkpoint_source_lock_unsafe", message)
        self.published_source = published_source


class CheckpointSourcePublishedValidationError(CheckpointSourceError):
    """A published source failed later validation while publication stayed known."""

    def __init__(
        self,
        code: str,
        message: str,
        *,
        published_source: "WorkspaceCheckpointSource",
    ) -> None:
        super().__init__(code, message)
        self.published_source = published_source


class CheckpointSourceFailureWithSafeWriterError(CheckpointSourceError):
    """A source integrity failure retained an exact active successor writer."""

    def __init__(
        self,
        cause: Exception,
        *,
        successor_lease: "WriterLease",
    ) -> None:
        code = getattr(cause, "code", "checkpoint_source_integrity_failed")
        if not isinstance(code, str) or re.fullmatch(
            r"[a-z][a-z0-9_]{0,127}", code
        ) is None:
            code = "checkpoint_source_integrity_failed"
        super().__init__(code, str(cause) or type(cause).__name__)
        self.published_source = getattr(cause, "published_source", None)
        self.successor_lease = successor_lease
        self.writer_reacquired = True


class CheckpointSourceWriterStateUnverifiedError(CheckpointSourceError):
    """A post-commit source handoff could not classify its current writer."""

    def __init__(
        self,
        message: str,
        *,
        published_source: "WorkspaceCheckpointSource | None",
        capture_failure_code: str | None = None,
        capture_error: BaseException | None = None,
    ) -> None:
        super().__init__("checkpoint_source_writer_state_unverified", message)
        self.published_source = published_source
        self.capture_failure_code = capture_failure_code
        self.capture_error = capture_error


class RawCaptureArtifactUnavailableError(WorkspaceStoreError):
    """One committed artifact is intentionally unavailable for ordinary use."""

    def __init__(
        self,
        *,
        capture_id: str,
        artifact_ordinal: int,
        disposition: str,
    ) -> None:
        self.capture_id = capture_id
        self.artifact_ordinal = artifact_ordinal
        self.disposition = disposition
        super().__init__(
            f"capture-artifact:{capture_id}#{artifact_ordinal} is unavailable for "
            f"ordinary research use ({disposition}); continue with other retained "
            "material and report this exact artifact to the external coordinator"
        )


class _OrdinarySecurityDispositionError(WorkspaceStoreError):
    """An exact ordinary-use dependency is intentionally security-disposed."""


class StaleWriterError(WorkspaceStoreError):
    pass


class StaleCommandError(WorkspaceStoreError):
    pass


class MissionHostStoreCutStaleError(StaleCommandError):
    """The private Host launch cut no longer equals the transaction prestate."""


class MissionFenceStaleCommandError(StaleCommandError):
    """An unchanged fence rejection with one safe source-owned diagnostic."""

    CODES = frozenset({
        "mission_fence_owner_epoch_binding_stale",
        "mission_fence_owner_epoch_state_stale",
        "mission_fence_store_epoch_state_stale",
        "mission_fence_store_authorized_root_stale",
        "mission_fence_store_target_stale",
        "mission_fence_store_predecessor_absent",
        "mission_fence_store_payload_mission_stale",
    })

    def __init__(self, message: str, *, diagnostic_code: str) -> None:
        if diagnostic_code not in self.CODES:
            raise ValueError("unsupported Mission fence diagnostic code")
        super().__init__(message)
        self.diagnostic_code = diagnostic_code


MISSION_FENCE_DIAGNOSTIC_STAGES = frozenset(
    {"owner_open", "host_binding", "owner", "writer", "store"}
)


@contextmanager
def mission_fence_diagnostic_stage(stage: str | None) -> Iterator[None]:
    """Attach only the innermost known fence stage; never change the exception."""

    if stage is not None and stage not in MISSION_FENCE_DIAGNOSTIC_STAGES:
        raise ValueError("unsupported Mission fence diagnostic stage")
    try:
        yield
    except Exception as exc:
        prior_stage = getattr(exc, "_mission_fence_stage", None)
        if stage is not None and (
            not isinstance(prior_stage, str)
            or prior_stage not in MISSION_FENCE_DIAGNOSTIC_STAGES
        ):
            setattr(exc, "_mission_fence_stage", stage)
        raise


