@dataclass(frozen=True, slots=True)
class WorkspaceCheckpointSource:
    """One reverified fixed-slot database source from a checkpoint handoff."""

    path: Path
    state: str
    claim_id: str | None
    source_incarnation: str
    mission_id: str
    checkpoint_id: str
    checkpoint_sha256: str
    checkpoint_project_commit: int
    project_id: str
    source_root_identity: str
    canonical_authority_digest: str
    prior_writer_epoch: int
    prior_writer_owner: str
    project_commit: int
    root_digest: str
    transition_head_digest: str | None
    schema_version: int
    operating_mode: str
    root_digest_version: int
    migration_digest: str
    schema_object_digest: str
    database_sha256: str
    byte_length: int

    def __post_init__(self) -> None:
        if self.state not in {"latest_unclaimed", "claimed"}:
            raise ValueError("checkpoint source state is unsupported")
        if (self.state == "claimed") != (self.claim_id is not None):
            raise ValueError("claimed checkpoint source requires one claim identity")
        if self.claim_id is not None and not _CHECKPOINT_SOURCE_CLAIM_RE.fullmatch(
            self.claim_id
        ):
            raise ValueError("checkpoint source claim identity is not portable")
        for value, label in (
            (self.source_incarnation, "source incarnation"),
            (self.checkpoint_sha256, "checkpoint digest"),
            (self.source_root_identity, "source root identity"),
            (self.canonical_authority_digest, "canonical authority digest"),
            (self.root_digest, "root digest"),
            (self.migration_digest, "migration digest"),
            (self.schema_object_digest, "schema object digest"),
            (self.database_sha256, "database digest"),
        ):
            if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None:
                raise ValueError(f"checkpoint source {label} must be lowercase SHA-256")
        if self.transition_head_digest is not None and re.fullmatch(
            r"[0-9a-f]{64}", self.transition_head_digest
        ) is None:
            raise ValueError("checkpoint source transition head must be lowercase SHA-256")
        if any(
            not isinstance(value, str) or not value
            for value in (
                self.mission_id,
                self.checkpoint_id,
                self.project_id,
                self.prior_writer_owner,
                self.operating_mode,
            )
        ):
            raise ValueError("checkpoint source text bindings must be non-empty")
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value < minimum
            for value, minimum in (
                (self.checkpoint_project_commit, 0),
                (self.prior_writer_epoch, 1),
                (self.project_commit, 0),
                (self.schema_version, 1),
                (self.root_digest_version, 1),
                (self.byte_length, 1),
            )
        ):
            raise ValueError("checkpoint source numeric bindings are invalid")

    def source_binding_payload(self) -> dict[str, Any]:
        """Return the path-free binding retained by pending ASR state and BackupSet."""

        return {
            "schema_version": "mathematical_research.checkpoint_source.v1",
            "source_incarnation": self.source_incarnation,
            "mission_id": self.mission_id,
            "checkpoint_id": self.checkpoint_id,
            "checkpoint_sha256": self.checkpoint_sha256,
            "checkpoint_project_commit": self.checkpoint_project_commit,
            "project_id": self.project_id,
            "source_root_identity": self.source_root_identity,
            "canonical_authority_digest": self.canonical_authority_digest,
            "prior_writer_epoch": self.prior_writer_epoch,
            "prior_writer_owner": self.prior_writer_owner,
            "project_commit": self.project_commit,
            "root_digest": self.root_digest,
            "transition_head_digest": self.transition_head_digest,
            "database_sha256": self.database_sha256,
            "database_length": self.byte_length,
        }


@dataclass(frozen=True, slots=True)
class CheckpointSourceHandoffResult:
    """Checkpoint remains complete; this reports source publication separately."""

    status: str
    checkpoint_completed: bool
    source: WorkspaceCheckpointSource | None
    successor_lease: WriterLease | None
    database_bytes: int | None
    handoff_elapsed_ms: int
    capture_failure_code: str | None = None
    capture_failure_message: str | None = None
    preserved_lease: WriterLease | None = None
    operation_failure_code: str | None = None
    operation_failure_message: str | None = None

    def __post_init__(self) -> None:
        if self.status not in {
            "published",
            "capture_failed_writer_reacquired",
            "snapshot_skipped_writer_preserved",
        }:
            raise ValueError("checkpoint source handoff status is unsupported")
        if not self.checkpoint_completed:
            raise ValueError("checkpoint source handoff cannot represent an open checkpoint")
        if (self.status == "published") != (self.source is not None):
            raise ValueError("checkpoint source handoff publication binding is inconsistent")
        if (self.status == "published") == (self.capture_failure_code is not None):
            raise ValueError("checkpoint source handoff failure binding is inconsistent")
        if (self.capture_failure_code is None) != (
            self.capture_failure_message is None
        ):
            raise ValueError("checkpoint source failure code and message must be paired")
        if (self.operation_failure_code is None) != (
            self.operation_failure_message is None
        ):
            raise ValueError(
                "checkpoint source operation failure code and message must be paired"
            )
        if self.operation_failure_code not in {None, "checkpoint_source_lock_unsafe"}:
            raise ValueError("checkpoint source operation failure code is unsupported")
        if self.database_bytes is None:
            if self.status != "snapshot_skipped_writer_preserved":
                raise ValueError(
                    "checkpoint source handoff measurement availability is invalid"
                )
        elif (
            isinstance(self.database_bytes, bool)
            or not isinstance(self.database_bytes, int)
            or self.database_bytes < 1
        ):
            raise ValueError("checkpoint source handoff database measurement is invalid")
        if (
            isinstance(self.handoff_elapsed_ms, bool)
            or not isinstance(self.handoff_elapsed_ms, int)
            or self.handoff_elapsed_ms < 0
        ):
            raise ValueError("checkpoint source handoff duration is invalid")
        writer_preserved = self.status == "snapshot_skipped_writer_preserved"
        if writer_preserved != (self.preserved_lease is not None):
            raise ValueError("checkpoint source preserved-writer binding is inconsistent")
        if writer_preserved == (self.successor_lease is not None):
            raise ValueError("checkpoint source active-writer binding is ambiguous")
        active_lease = self.preserved_lease if writer_preserved else self.successor_lease
        assert active_lease is not None
        active_lease.verify_issued()




@dataclass(frozen=True, slots=True)
class CandidateA1StoreBinding:
    """Store-issued exact Candidate-to-incumbent-A1 persistence binding."""

    project_id: str
    root_identity: str
    project_commit: int
    root_digest: str
    canonical_authority_digest: str
    candidate_id: str
    candidate_revision: int
    candidate_digest: str
    package_digest: str
    intake_id: str
    evidence_id: str
    evidence_revision: int
    evidence_payload_digest: str
    artifact_digest: str
    closure_id: str
    closure_digest: str
    alert_id: str
    hold_id: str
    scope: tuple[str, ...]
    hold_lifecycle: str
    triage_disposition: str | None
    triage_evidence_id: str | None
    triage_evidence_revision: int | None
    triage_evidence_payload_digest: str | None
    triage_record: Mapping[str, Any] | None
    triage_source: Mapping[str, Any] | None
    admission_decision_id: str | None
    admission_decision_digest: str | None
    admitted_result: Mapping[str, Any] | None
    admission_rejection: Mapping[str, Any] | None
    admission_project_commit: int | None
    admission_transition_digest: str | None
    resolution_id: str | None
    resolution_authorization: Mapping[str, Any] | None
    resolution: Mapping[str, Any] | None
    resolution_digest: str | None
    canonical_effect: str = "none"
    mathematical_effect: str = "none"
    _issuance_tag: bytes | None = field(
        default=None, init=False, repr=False, compare=False
    )

    def __post_init__(self) -> None:
        object.__setattr__(self, "scope", tuple(self.scope))
        if self.resolution_authorization is not None:
            object.__setattr__(
                self,
                "resolution_authorization",
                deep_freeze(self.resolution_authorization),
            )
        if self.resolution is not None:
            object.__setattr__(self, "resolution", deep_freeze(self.resolution))
        if self.triage_record is not None:
            object.__setattr__(
                self,
                "triage_record",
                deep_freeze(self.triage_record),
            )
        if self.triage_source is not None:
            object.__setattr__(
                self,
                "triage_source",
                deep_freeze(self.triage_source),
            )
        if self.admitted_result is not None:
            object.__setattr__(
                self,
                "admitted_result",
                deep_freeze(self.admitted_result),
            )
        if self.admission_rejection is not None:
            object.__setattr__(
                self,
                "admission_rejection",
                deep_freeze(self.admission_rejection),
            )
        for label, value in (
            ("root digest", self.root_digest),
            ("canonical authority", self.canonical_authority_digest),
            ("Candidate", self.candidate_digest),
            ("package", self.package_digest),
            ("Evidence payload", self.evidence_payload_digest),
            ("artifact", self.artifact_digest),
            ("closure", self.closure_digest),
        ):
            if (
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
            ):
                raise ValueError(f"{label} digest must be lowercase SHA-256")
        if self.artifact_digest != self.candidate_digest:
            raise ValueError("A1 artifact must be the exact Candidate document bytes")
        if self.candidate_revision < 1 or self.evidence_revision < 1:
            raise ValueError("Candidate and Evidence revisions must be positive")
        if self.hold_lifecycle not in {"open", "resolved"}:
            raise ValueError("Candidate A1 lifecycle must be open or resolved")
        has_resolution = self.resolution_id is not None
        admission_decision_values = (
            self.admission_decision_id,
            self.admission_decision_digest,
        )
        admitted_result_values = (
            self.admitted_result,
            self.admission_project_commit,
            self.admission_transition_digest,
        )
        has_admission = self.admission_decision_id is not None
        has_admitted_result = self.admitted_result is not None
        has_admission_rejection = self.admission_rejection is not None
        if any(
            (value is None) != (not has_admission)
            for value in admission_decision_values
        ):
            raise ValueError("Candidate A1 Admission Decision fields are not exact")
        if any(
            (value is None) != (not has_admitted_result)
            for value in admitted_result_values
        ):
            raise ValueError("Candidate A1 admitted-result fields are not exact")
        if has_admission != (has_admitted_result or has_admission_rejection) or (
            has_admitted_result and has_admission_rejection
        ):
            raise ValueError("Candidate A1 Admission terminal kind is not exact")
        triage_values = (
            self.triage_disposition,
            self.triage_evidence_id,
            self.triage_evidence_revision,
            self.triage_evidence_payload_digest,
            self.triage_record,
            self.triage_source,
        )
        has_triage = self.triage_disposition is not None
        if any((value is None) != (not has_triage) for value in triage_values):
            raise ValueError("Candidate A1 triage fields are not exact")
        if has_resolution and (has_triage or has_admission):
            raise ValueError(
                "Candidate A1 cannot combine retired resolution with current Admission"
            )
        triage_invalidated = self.triage_disposition == CANDIDATE_A1_TRIAGE_INVALIDATED
        if (self.hold_lifecycle == "resolved") != (
            has_resolution or triage_invalidated or has_admission
        ) or any(
            (value is None) != (not has_resolution)
            for value in (
                self.resolution_authorization,
                self.resolution,
                self.resolution_digest,
            )
        ):
            raise ValueError("Candidate A1 resolution fields are not exact")
        if has_triage:
            if self.triage_disposition not in {
                CANDIDATE_A1_TRIAGE_INVALIDATED,
                CANDIDATE_A1_TRIAGE_ADMISSION_READY,
            }:
                raise ValueError("Candidate A1 triage disposition is not closed")
            if self.triage_evidence_revision != 1:
                raise ValueError("Candidate A1 triage revision must be exactly 1")
            if (
                not isinstance(self.triage_evidence_payload_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", self.triage_evidence_payload_digest)
                is None
            ):
                raise ValueError("Candidate A1 triage digest is invalid")
            expected_id = candidate_a1_triage_evidence_id(
                candidate_id=self.candidate_id,
                candidate_revision=self.candidate_revision,
                candidate_digest_sha256=self.candidate_digest,
            )
            if self.triage_evidence_id != expected_id:
                raise ValueError("Candidate A1 triage Evidence identity is stale")
            record = self.triage_record
            assert record is not None
            evidence = EvidenceItemRevision(
                evidence_id=str(record["evidence_id"]),
                revision=int(record["revision"]),
                subtype=str(record["subtype"]),
                subject=record["subject"],
                exact_scope=str(record["exact_scope"]),
                rigor=str(record["rigor"]),
                limitations=tuple(str(item) for item in record["limitations"]),
                non_inferences=tuple(str(item) for item in record["non_inferences"]),
                security_classification=str(record["security_classification"]),
                retention=str(record["retention"]),
                blob_roles=tuple(
                    (str(item[0]), str(item[1])) for item in record["blob_roles"]
                ),
                availability_state=str(record["availability_state"]),
                canonical_effect=str(record["canonical_effect"]),
            )
            triage = candidate_a1_triage_from_evidence(evidence)
            if (
                triage.disposition != self.triage_disposition
                or triage.payload_digest != self.triage_evidence_payload_digest
            ):
                raise ValueError("Candidate A1 triage readback is stale")
        if has_admitted_result:
            admitted = self.admitted_result
            assert admitted is not None
            decision_ref = admitted.get("admission_decision_ref")
            candidate_ref = admitted.get("candidate_ref")
            if (
                self.triage_disposition != CANDIDATE_A1_TRIAGE_ADMISSION_READY
                or set(admitted)
                != {
                    "target",
                    "disposition",
                    "theorem_or_counterexample_claim",
                    "candidate_ref",
                    "admission_decision_ref",
                }
                or admitted.get("target") != "riemann_hypothesis"
                or admitted.get("disposition") not in {"proved", "disproved"}
                or not isinstance(candidate_ref, Mapping)
                or set(candidate_ref)
                != {
                    "mission_id",
                    "candidate_id",
                    "revision",
                    "digest_sha256",
                }
                or not isinstance(candidate_ref.get("mission_id"), str)
                or not candidate_ref["mission_id"]
                or candidate_ref.get("candidate_id") != self.candidate_id
                or candidate_ref.get("revision") != self.candidate_revision
                or candidate_ref.get("digest_sha256") != self.candidate_digest
                or not isinstance(decision_ref, Mapping)
                or decision_ref
                != {
                    "decision_id": self.admission_decision_id,
                    "digest_sha256": self.admission_decision_digest,
                }
                or not isinstance(self.admission_decision_digest, str)
                or re.fullmatch(
                    r"[0-9a-f]{64}", self.admission_decision_digest
                )
                is None
                or not isinstance(self.admission_project_commit, int)
                or isinstance(self.admission_project_commit, bool)
                or self.admission_project_commit < 1
                or not isinstance(self.admission_transition_digest, str)
                or re.fullmatch(
                    r"[0-9a-f]{64}", self.admission_transition_digest
                )
                is None
            ):
                raise ValueError("Candidate A1 Admission terminal binding is stale")
        if has_admission_rejection:
            rejection = self.admission_rejection
            assert rejection is not None
            candidate_ref = rejection.get("candidate_ref")
            decision_ref = rejection.get("admission_decision_ref")
            objections = rejection.get("objections")
            cited_basis = rejection.get("cited_basis")
            try:
                normalized_cited_basis = tuple(
                    AdmissionOwnerRevisionRef.from_payload(item)
                    for item in cited_basis
                )
            except (TypeError, ValueError):
                normalized_cited_basis = ()
            if (
                self.triage_disposition != CANDIDATE_A1_TRIAGE_ADMISSION_READY
                or set(rejection)
                != {
                    "disposition",
                    "candidate_ref",
                    "admission_decision_ref",
                    "objections",
                    "cited_basis",
                }
                or rejection.get("disposition") != "independently_invalidated"
                or not isinstance(candidate_ref, Mapping)
                or set(candidate_ref)
                != {
                    "mission_id",
                    "candidate_id",
                    "revision",
                    "digest_sha256",
                }
                or not isinstance(candidate_ref.get("mission_id"), str)
                or not candidate_ref["mission_id"]
                or candidate_ref.get("candidate_id") != self.candidate_id
                or candidate_ref.get("revision") != self.candidate_revision
                or candidate_ref.get("digest_sha256") != self.candidate_digest
                or decision_ref
                != {
                    "decision_id": self.admission_decision_id,
                    "digest_sha256": self.admission_decision_digest,
                }
                or not isinstance(objections, (list, tuple))
                or not objections
                or any(
                    not isinstance(item, Mapping)
                    or set(item)
                    != {"exact_objection", "affected_scope", "materiality_basis"}
                    or any(
                        not isinstance(item[key], str) or not item[key].strip()
                        for key in (
                            "exact_objection",
                            "affected_scope",
                            "materiality_basis",
                        )
                    )
                    for item in objections
                )
                or not isinstance(cited_basis, (list, tuple))
                or not cited_basis
                or len(normalized_cited_basis) != len(cited_basis)
                or normalized_cited_basis != tuple(sorted(normalized_cited_basis))
                or len(normalized_cited_basis) != len(set(normalized_cited_basis))
                or not isinstance(self.admission_decision_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", self.admission_decision_digest)
                is None
            ):
                raise ValueError("Candidate A1 Admission rejection binding is stale")
        if has_resolution:
            if set(self.resolution_authorization or {}) != {
                "command_request_digest",
                "principal_id",
                "review_context_id",
                "resolution_authorization_digest",
            }:
                raise ValueError("Candidate A1 resolution authorization is incomplete")
            for key in (
                "command_request_digest",
                "resolution_authorization_digest",
            ):
                value = self.resolution_authorization[key]
                if (
                    not isinstance(value, str)
                    or re.fullmatch(r"[0-9a-f]{64}", value) is None
                ):
                    raise ValueError(
                        "Candidate A1 resolution authorization digest is invalid"
                    )
            for key in ("principal_id", "review_context_id"):
                _require_text(
                    self.resolution_authorization[key],
                    f"Candidate A1 resolution {key}",
                )
            expected = _digest(
                canonical_json_bytes(
                    {
                        "resolution_id": self.resolution_id,
                        "authorization": deep_thaw(self.resolution_authorization),
                        "resolution": deep_thaw(self.resolution),
                    }
                )
            )
            if self.resolution_digest != expected:
                raise ValueError("Candidate A1 resolution digest is stale")
        if self.canonical_effect != "none" or self.mathematical_effect != "none":
            raise ValueError("Candidate A1 binding remains proof-neutral")

    def to_mapping(self) -> dict[str, Any]:
        return {
            "project_id": self.project_id,
            "root_identity": self.root_identity,
            "project_commit": self.project_commit,
            "root_digest": self.root_digest,
            "canonical_authority_digest": self.canonical_authority_digest,
            "candidate_id": self.candidate_id,
            "candidate_revision": self.candidate_revision,
            "candidate_digest": self.candidate_digest,
            "package_digest": self.package_digest,
            "intake_id": self.intake_id,
            "evidence_id": self.evidence_id,
            "evidence_revision": self.evidence_revision,
            "evidence_payload_digest": self.evidence_payload_digest,
            "artifact_digest": self.artifact_digest,
            "closure_id": self.closure_id,
            "closure_digest": self.closure_digest,
            "alert_id": self.alert_id,
            "hold_id": self.hold_id,
            "scope": list(self.scope),
            "hold_lifecycle": self.hold_lifecycle,
            "triage_disposition": self.triage_disposition,
            "triage_evidence_id": self.triage_evidence_id,
            "triage_evidence_revision": self.triage_evidence_revision,
            "triage_evidence_payload_digest": self.triage_evidence_payload_digest,
            "triage_record": deep_thaw(self.triage_record),
            "triage_source": deep_thaw(self.triage_source),
            "admission_decision_id": self.admission_decision_id,
            "admission_decision_digest": self.admission_decision_digest,
            "admitted_result": deep_thaw(self.admitted_result),
            "admission_rejection": deep_thaw(self.admission_rejection),
            "admission_project_commit": self.admission_project_commit,
            "admission_transition_digest": self.admission_transition_digest,
            "resolution_id": self.resolution_id,
            "resolution_authorization": deep_thaw(self.resolution_authorization),
            "resolution": deep_thaw(self.resolution),
            "resolution_digest": self.resolution_digest,
            "canonical_effect": self.canonical_effect,
            "mathematical_effect": self.mathematical_effect,
        }

    @property
    def digest_sha256(self) -> str:
        return _digest(canonical_json_bytes(self.to_mapping()))

    def verify_issued(self) -> None:
        if type(self) is not CandidateA1StoreBinding:
            raise WorkspaceIntegrityError(
                "Candidate A1 binding subclasses are not store-issued"
            )
        expected = _candidate_a1_store_binding_tag(self)
        if self._issuance_tag is None or not hmac.compare_digest(
            self._issuance_tag, expected
        ):
            raise WorkspaceIntegrityError(
                "Candidate A1 binding was not issued by this store process"
            )






_CANDIDATE_A1_STORE_BINDING_KEY = os.urandom(32)




def _candidate_a1_store_binding_tag(value: CandidateA1StoreBinding) -> bytes:
    return hmac.new(
        _CANDIDATE_A1_STORE_BINDING_KEY,
        canonical_json_bytes(value.to_mapping()),
        hashlib.sha256,
    ).digest()


def _issue_candidate_a1_store_binding(
    **values: Any,
) -> CandidateA1StoreBinding:
    binding = CandidateA1StoreBinding(**values)
    object.__setattr__(
        binding,
        "_issuance_tag",
        _candidate_a1_store_binding_tag(binding),
    )
    binding.verify_issued()
    return binding








@dataclass(frozen=True, slots=True)
class VerifiedEvidenceClosureBundle:
    """Immutable, store-derived closure plus its exact committed Blob records."""

    project_id: str
    root_identity: str
    project_commit: int
    project_root_digest: str
    manifest: ClosureManifest
    blobs: tuple[BlobRecord, ...]
    canonical_effect: str = "none"
    _issuance_tag: bytes | None = field(
        default=None, init=False, repr=False, compare=False
    )

    def __post_init__(self) -> None:
        if self.project_commit < 0 or self.canonical_effect != "none":
            raise ValueError(
                "verified closure bundles are proof-neutral committed snapshots"
            )
        if tuple(record.sha256 for record in self.blobs) != tuple(
            sorted(self.manifest.blob_sha256s)
        ):
            raise ValueError("verified closure bundle Blob inventory is not exact")

    @property
    def blob_records(self) -> Mapping[str, BlobRecord]:
        return MappingProxyType({record.sha256: record for record in self.blobs})

    def verify_issued(self) -> None:
        if type(self) is not VerifiedEvidenceClosureBundle:
            raise WorkspaceIntegrityError(
                "verified Evidence closure bundle subclasses have no authority"
            )
        expected = _verified_evidence_bundle_tag(self)
        if self._issuance_tag is None or not hmac.compare_digest(
            self._issuance_tag, expected
        ):
            raise WorkspaceIntegrityError(
                "verified Evidence closure bundle was not issued by this store process"
            )


_VERIFIED_EVIDENCE_BUNDLE_KEY = os.urandom(32)


@dataclass(frozen=True, slots=True)
class VerifiedEvidenceRevision:
    """One Store/CAS-verified Evidence revision and its exact immutable bytes."""

    project_id: str
    root_identity: str
    project_commit: int
    project_root_digest: str
    canonical_authority_digest: str
    evidence: EvidenceItemRevision
    payload_digest: str
    is_current_head: bool
    closure: VerifiedEvidenceClosureBundle | None
    blob_bytes: tuple[tuple[str, str, bytes], ...]
    provenance: tuple[Mapping[str, Any], ...]
    independence_disclosures: tuple[Mapping[str, Any], ...]
    canonical_effect: str = "none"
    _issuance_tag: bytes | None = field(
        default=None, init=False, repr=False, compare=False
    )

    def __post_init__(self) -> None:
        if (
            self.project_commit < 0
            or self.canonical_effect != "none"
            or type(self.evidence) is not EvidenceItemRevision
            or self.evidence.availability_state != "verified_available"
        ):
            raise ValueError(
                "verified Evidence revisions are proof-neutral available snapshots"
            )
        for digest in (
            self.project_root_digest,
            self.canonical_authority_digest,
            self.payload_digest,
        ):
            if re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                raise ValueError("verified Evidence revision digest is invalid")
        if canonical_payload(self.evidence.to_payload()).sha256 != self.payload_digest:
            raise ValueError("verified Evidence revision payload digest is stale")
        expected_roles = tuple(self.evidence.blob_roles)
        actual_roles = tuple((role, digest) for role, digest, _raw in self.blob_bytes)
        if actual_roles != expected_roles:
            raise ValueError("verified Evidence revision Blob order is not exact")
        for _role, digest, raw in self.blob_bytes:
            if hashlib.sha256(raw).hexdigest() != digest:
                raise ValueError("verified Evidence revision Blob bytes are stale")
        object.__setattr__(
            self,
            "provenance",
            tuple(deep_freeze(item) for item in self.provenance),
        )
        object.__setattr__(
            self,
            "independence_disclosures",
            tuple(deep_freeze(item) for item in self.independence_disclosures),
        )

    def verify_issued(self) -> None:
        if type(self) is not VerifiedEvidenceRevision:
            raise WorkspaceIntegrityError(
                "verified Evidence revision subclasses have no authority"
            )
        expected = _verified_evidence_revision_tag(self)
        if self._issuance_tag is None or not hmac.compare_digest(
            self._issuance_tag, expected
        ):
            raise WorkspaceIntegrityError(
                "verified Evidence revision was not issued by this Store process"
            )


_VERIFIED_EVIDENCE_REVISION_KEY = os.urandom(32)


def _verified_evidence_revision_tag(value: VerifiedEvidenceRevision) -> bytes:
    return hmac.new(
        _VERIFIED_EVIDENCE_REVISION_KEY,
        canonical_json_bytes(
            {
                "project_id": value.project_id,
                "root_identity": value.root_identity,
                "project_commit": value.project_commit,
                "project_root_digest": value.project_root_digest,
                "canonical_authority_digest": value.canonical_authority_digest,
                "evidence": value.evidence.to_payload(),
                "payload_digest": value.payload_digest,
                "is_current_head": value.is_current_head,
                "closure_digest": (
                    value.closure.manifest.manifest_sha256
                    if value.closure is not None
                    else None
                ),
                "blob_bytes": [
                    {
                        "role": role,
                        "sha256": digest,
                        "byte_length": len(raw),
                    }
                    for role, digest, raw in value.blob_bytes
                ],
                "provenance": list(value.provenance),
                "independence_disclosures": list(value.independence_disclosures),
                "canonical_effect": value.canonical_effect,
            }
        ),
        hashlib.sha256,
    ).digest()


def _issue_verified_evidence_revision(
    **values: Any,
) -> VerifiedEvidenceRevision:
    revision = VerifiedEvidenceRevision(**values)
    object.__setattr__(
        revision,
        "_issuance_tag",
        _verified_evidence_revision_tag(revision),
    )
    revision.verify_issued()
    return revision


def _verified_evidence_bundle_tag(bundle: VerifiedEvidenceClosureBundle) -> bytes:
    return hmac.new(
        _VERIFIED_EVIDENCE_BUNDLE_KEY,
        canonical_json_bytes(
            {
                "project_id": bundle.project_id,
                "root_identity": bundle.root_identity,
                "project_commit": bundle.project_commit,
                "project_root_digest": bundle.project_root_digest,
                "manifest": bundle.manifest.to_payload(),
                "blobs": [record.to_payload() for record in bundle.blobs],
                "canonical_effect": bundle.canonical_effect,
            }
        ),
        hashlib.sha256,
    ).digest()


def _issue_verified_evidence_bundle(
    **values: Any,
) -> VerifiedEvidenceClosureBundle:
    bundle = VerifiedEvidenceClosureBundle(**values)
    object.__setattr__(bundle, "_issuance_tag", _verified_evidence_bundle_tag(bundle))
    bundle.verify_issued()
    return bundle


