@dataclass(frozen=True, slots=True)
class _AuxiliarySpec:
    columns: tuple[str, ...]
    required: frozenset[str]
    json_columns: frozenset[str]
    primary_key: tuple[str, ...]
    constants: Mapping[str, Any] = field(default_factory=dict)
    auto_created_at: bool = False
    auto_project_commit: bool = False
    logical_path_columns: frozenset[str] = frozenset()
    stored_row_digest: bool = False


def _spec(
    columns: str,
    required: str,
    primary_key: str,
    *,
    json_columns: str = "",
    constants: Mapping[str, Any] | None = None,
    auto_created_at: bool = False,
    auto_project_commit: bool = False,
    logical_path_columns: str = "",
    stored_row_digest: bool = False,
) -> _AuxiliarySpec:
    return _AuxiliarySpec(
        columns=tuple(columns.split()),
        required=frozenset(required.split()),
        json_columns=frozenset(json_columns.split()),
        primary_key=tuple(primary_key.split()),
        constants=MappingProxyType(dict(constants or {})),
        auto_created_at=auto_created_at,
        auto_project_commit=auto_project_commit,
        logical_path_columns=frozenset(logical_path_columns.split()),
        stored_row_digest=stored_row_digest,
    )


