def _prepare_auxiliary_write(
    write: AuxiliaryWrite,
    *,
    paths: WorkspacePaths,
    created_at: str,
    project_commit_no: int,
    auxiliary_specs: Mapping[AuxiliaryTable, _AuxiliarySpec] = _AUXILIARY_SPECS,
) -> _PreparedAuxiliary:
    if write.table is AuxiliaryTable.EVIDENCE_ITEM_HEAD:
        raise ValueError(
            "Evidence heads advance only through typed EvidenceHeadAdvance expectations"
        )
    try:
        spec = auxiliary_specs[write.table]
    except KeyError as exc:
        raise ValueError(
            f"{write.table.value} is unavailable under the current root contract"
        ) from exc
    supplied = set(write.values)
    unknown = sorted(supplied - set(spec.columns))
    if unknown:
        raise ValueError(
            f"{write.table.value} auxiliary row has unknown columns: {', '.join(unknown)}"
        )
    missing = sorted(
        column for column in spec.required if write.values.get(column) is None
    )
    if missing:
        raise ValueError(
            f"{write.table.value} auxiliary row is missing columns: {', '.join(missing)}"
        )

    values: dict[str, Any] = {
        column: write.values.get(column) for column in spec.columns
    }
    for column, expected in spec.constants.items():
        supplied_value = values.get(column)
        if supplied_value is not None and supplied_value != expected:
            raise ValueError(f"{write.table.value}.{column} must remain {expected!r}")
        values[column] = expected
    if spec.auto_created_at and values.get("created_at") is None:
        values["created_at"] = created_at
    if (
        write.table is AuxiliaryTable.ADMISSION_CANONICAL_TRANSACTION
        and values.get("updated_at") is None
    ):
        values["updated_at"] = created_at
    if spec.auto_project_commit:
        supplied_commit = values.get("project_commit_no")
        if supplied_commit is not None and supplied_commit != project_commit_no:
            raise ValueError(
                f"{write.table.value}.project_commit_no must equal the committing project revision"
            )
        values["project_commit_no"] = project_commit_no

    for column in spec.json_columns:
        value = values[column]
        if value is None:
            continue
        values[column] = canonical_json_bytes(value).decode("utf-8")
    for column in spec.logical_path_columns:
        logical = normalize_logical_path(str(values[column]))
        paths.resolve_logical(logical)
        values[column] = logical
    if write.table is AuxiliaryTable.BLOB:
        digest = str(values["sha256"]).casefold()
        expected_path = f"cas/sha256/{digest[:2]}/{digest[2:]}"
        if values["logical_cas_path"] != expected_path:
            raise ValueError("blob logical_cas_path must be derived from its SHA-256")

    for column, value in values.items():
        if isinstance(value, bool):
            values[column] = int(value)
            value = values[column]
        if value is not None and (
            column == "sha256"
            or column.endswith("_digest")
            or column.endswith("_sha256")
        ):
            digest = str(value).casefold()
            if len(digest) != 64 or any(
                character not in "0123456789abcdef" for character in digest
            ):
                raise ValueError(
                    f"{write.table.value}.{column} must be a SHA-256 hex digest"
                )
            values[column] = digest
        if value is not None and not isinstance(value, (str, int)):
            raise TypeError(
                f"{write.table.value}.{column} must be a scalar or a declared JSON column"
            )
    for column in spec.primary_key:
        if values[column] in {None, ""}:
            raise ValueError(f"{write.table.value}.{column} must identify the row")

    row_payload = {
        "table": write.table.value,
        "values": {column: values[column] for column in spec.columns},
    }
    return _PreparedAuxiliary(
        table=write.table,
        values=MappingProxyType(values),
        row_digest=_digest(canonical_json_bytes(row_payload)),
    )


