    def read_complete_claim_admission_case(
        self,
        case_ref: AdmissionEvidenceRef,
    ) -> AdmissionCaseRecord:
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            if int(self._metadata(connection)["root_digest_version"]) == 6:
                self._verify_current_boundary(connection)
            return _admission_case_from_connection(
                connection, case_ref, cas=EvidenceCAS(self.paths)
            )

    def read_complete_claim_admission_review(
        self,
        review_ref: AdmissionEvidenceRef,
    ) -> AdmissionReviewRecord:
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            if int(self._metadata(connection)["root_digest_version"]) == 6:
                self._verify_current_boundary(connection)
            return _admission_review_from_connection(
                connection, review_ref, cas=EvidenceCAS(self.paths)
            )

    def read_complete_claim_admission_decision(
        self,
        decision_ref: AdmissionEvidenceRef,
    ) -> AdmissionDecisionRecord:
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            if int(self._metadata(connection)["root_digest_version"]) == 6:
                self._verify_current_boundary(connection)
            evidence = _admission_evidence_from_connection(
                connection,
                evidence_id=decision_ref.evidence_id,
                subtype=ADMISSION_DECISION_EVIDENCE_SUBTYPE,
                cas=EvidenceCAS(self.paths),
            )
            if evidence is None:
                raise StaleCommandError("Admission Decision is absent")
            record = admission_decision_from_evidence(evidence)
            if record.payload_digest != decision_ref.payload_sha256 or decision_ref.revision != 1:
                raise StaleCommandError("Admission Decision ref is stale")
            return record

    def rebind_admitted_result(
        self,
        *,
        mission_id: str,
        admission_decision_ref: AdmissionEvidenceRef,
        source_canonical_authority_digest: str,
        target_canonical_snapshot: CanonicalStateSnapshot,
        selected_release_sha: str,
        dry_run: bool = False,
    ) -> AdmittedResultRebindResult:
        """Bind one admitted result while the Mission is inactive at checkpoint.

        This is the sole Mathematical-Research Store mutation used by the
        operator-owned canonical writer.  It does not decide mathematics,
        alter owner heads, admit a successor, or publish anything.  It only
        advances the Workspace's canonical authority to the exact selected
        release whose Research State already contains the Decision-derived
        admitted result.
        """

        mission_id = _require_text(mission_id, "mission_id")
        if type(dry_run) is not bool:
            raise TypeError("dry_run must be bool")
        if type(admission_decision_ref) is not AdmissionEvidenceRef:
            raise TypeError(
                "admitted-result rebind requires an exact AdmissionEvidenceRef"
            )
        if (
            not isinstance(source_canonical_authority_digest, str)
            or re.fullmatch(
                r"[0-9a-f]{64}", source_canonical_authority_digest
            )
            is None
        ):
            raise ValueError(
                "source_canonical_authority_digest must be lowercase SHA-256"
            )
        if (
            not isinstance(selected_release_sha, str)
            or re.fullmatch(r"[0-9a-f]{40}", selected_release_sha) is None
        ):
            raise ValueError("selected_release_sha must be one full Git SHA")

        target_authority = _verified_live_canonical_authority(
            target_canonical_snapshot
        )
        target_authority_payload = canonical_payload(target_authority)
        if target_authority["source_commit"] != selected_release_sha:
            raise StaleCommandError(
                "selected release differs from the target canonical snapshot"
            )

        request = {
            "contract": _ADMITTED_RESULT_REBIND_CONTRACT,
            "project_id": self.project_id,
            "mission_id": mission_id,
            "admission_decision_ref": admission_decision_ref.to_payload(),
            "source_canonical_authority_digest": (
                source_canonical_authority_digest
            ),
            "target_canonical_authority_digest": target_authority_payload.sha256,
            "selected_release_sha": selected_release_sha,
        }
        command_material = canonical_payload(request)
        command_id = f"admitted-result-rebind:{command_material.sha256}"
        bound_request = canonical_payload(
            {
                "project_id": self.project_id,
                "root_identity": self.paths.root_identity,
                "command_id": command_id,
                "command_kind": _ADMITTED_RESULT_REBIND_COMMAND_KIND,
                "actor": _ADMITTED_RESULT_REBIND_ACTOR,
                "request": request,
                "canonical_effect": "exact_authorized_delta",
            }
        )
        now = self._clock()
        outcome: CommandOutcome
        cas = EvidenceCAS(self.paths)

        with self._connection() as connection:
            self.paths.revalidate_physical(
                require_root=True, require_database=True
            )
            connection.execute("BEGIN IMMEDIATE")
            try:
                replay = self._replay_if_present(
                    connection,
                    command_id=command_id,
                    actor=_ADMITTED_RESULT_REBIND_ACTOR,
                    request_digest=bound_request.sha256,
                )
                if replay is not None:
                    connection.execute("ROLLBACK")
                    outcome = replay
                else:
                    metadata = self._metadata(connection)
                    if int(metadata["root_digest_version"]) == 6:
                        self._verify_current_boundary(connection)
                    source_authority = _validated_current_canonical_authority_json(
                        str(metadata["canonical_authority_json"])
                    )
                    if not is_direct_mission_generation(
                        int(metadata["schema_version"]),
                        int(metadata["root_digest_version"]),
                        str(metadata["operating_mode"]),
                    ):
                        raise WorkspaceIntegrityError(
                            "admitted-result rebind requires a supported direct Mission store"
                        )
                    if (
                        metadata["current_writer_epoch"] is not None
                        or str(metadata["lifecycle"]) != "quiesced"
                    ):
                        raise StaleWriterError(
                            "admitted-result rebind requires one inactive quiesced Mission"
                        )
                    if (
                        str(metadata["canonical_authority_digest"])
                        != source_canonical_authority_digest
                        or canonical_payload(source_authority).sha256
                        != source_canonical_authority_digest
                    ):
                        raise StaleCommandError(
                            "admitted-result rebind source canonical authority is stale"
                        )
                    if source_canonical_authority_digest == (
                        target_authority_payload.sha256
                    ):
                        raise StaleCommandError(
                            "canonical authority already equals the selected target without the exact rebind"
                        )

                    active_epochs = _operation_active_executive_epoch_chains(
                        connection,
                        mission_id,
                    )
                    checkpoint = _operation_latest_mission_checkpoint(
                        connection,
                        mission_id,
                    )
                    latest_epoch_event = connection.execute(
                        "SELECT executive_epoch_id, event_kind, project_commit_no "
                        "FROM executive_epoch_event WHERE mission_id = ? "
                        "ORDER BY project_commit_no DESC, event_ordinal DESC LIMIT 1",
                        (mission_id,),
                    ).fetchone()
                    if (
                        active_epochs
                        or checkpoint is None
                        or latest_epoch_event is None
                        or str(latest_epoch_event["event_kind"]) != "checkpointed"
                        or str(latest_epoch_event["executive_epoch_id"])
                        != checkpoint["executive_epoch_id"]
                        or int(latest_epoch_event["project_commit_no"])
                        != int(checkpoint["project_commit_no"])
                    ):
                        raise StaleCommandError(
                            "admitted-result rebind requires the exact natural checkpoint boundary"
                        )

                    strategy_root = _mission_strategy_root_from_connection(
                        connection,
                        mission_id,
                    )
                    if deep_thaw(checkpoint["document"].get("strategy_root")) != (
                        deep_thaw(strategy_root)
                    ):
                        raise StaleCommandError(
                            "admitted-result rebind requires the checkpoint's exact current Strategy"
                        )
                    strategy_row = _typed_head_from_connection(
                        connection,
                        TypedWorkspaceId(
                            IdentityKind.STRATEGY,
                            str(strategy_root["identity"]),
                        ),
                    )
                    if strategy_row is None:
                        raise WorkspaceIntegrityError(
                            "admitted-result rebind current Strategy is absent"
                        )
                    strategy_document = loads_strict_json_object(
                        str(strategy_row["payload_json"])
                    )
                    if strategy_document.get("mission_continuation") != "continue":
                        raise StaleCommandError(
                            "admitted-result rebind cannot reinterpret a historical "
                            "pause or unsolved closeout as canonical-result closeout"
                        )

                    evidence = _admission_evidence_from_connection(
                        connection,
                        evidence_id=admission_decision_ref.evidence_id,
                        subtype=ADMISSION_DECISION_EVIDENCE_SUBTYPE,
                        cas=cas,
                    )
                    if evidence is None:
                        raise StaleCommandError(
                            "admitted-result rebind Admission Decision is absent"
                        )
                    decision = admission_decision_from_evidence(evidence)
                    if (
                        admission_decision_ref.revision != 1
                        or decision.payload_digest
                        != admission_decision_ref.payload_sha256
                        or decision.disposition != ADMISSION_DECISION_AUTHORIZE
                        or decision.candidate_ref.mission_id != mission_id
                    ):
                        raise StaleCommandError(
                            "admitted-result rebind requires one exact authorizing Decision"
                        )

                    candidate_ref = decision.candidate_ref
                    candidate_row = connection.execute(
                        "SELECT payload_json, payload_digest FROM candidate_revision "
                        "WHERE object_id = ? AND revision = ?",
                        (candidate_ref.candidate_id, candidate_ref.revision),
                    ).fetchone()
                    if (
                        candidate_row is None
                        or str(candidate_row["payload_digest"])
                        != candidate_ref.digest_sha256
                    ):
                        raise StaleCommandError(
                            "admitted-result rebind Candidate is absent or stale"
                        )
                    candidate = loads_strict_json_object(
                        str(candidate_row["payload_json"])
                    )
                    a1 = _candidate_a1_material(
                        self,
                        connection,
                        candidate=candidate,
                        candidate_revision=candidate_ref.revision,
                        candidate_digest=candidate_ref.digest_sha256,
                        metadata=metadata,
                        require_open=True,
                        cas=cas,
                    )
                    if a1["triage_disposition"] != (
                        CANDIDATE_A1_TRIAGE_ADMISSION_READY
                    ):
                        raise StaleCommandError(
                            "admitted-result rebind requires admission_ready A1 triage"
                        )

                    from .canonical_admission import admitted_result_from_decision

                    admitted_result = admitted_result_from_decision(decision)
                    target_project = target_canonical_snapshot.state.get("project")
                    if (
                        not isinstance(target_project, Mapping)
                        or target_project.get("id") != self.project_id
                        or target_project.get("proof_status")
                        != admitted_result["disposition"]
                        or deep_thaw(target_project.get("admitted_result"))
                        != admitted_result
                        or "active_target" in target_project
                    ):
                        raise StaleCommandError(
                            "selected release does not contain the exact admitted result"
                        )

                    checkpoint_ref = {
                        "checkpoint_id": checkpoint["checkpoint_id"],
                        "payload_sha256": checkpoint["payload_digest"],
                    }
                    authorization = {
                        "authority_kind": "admitted_result_rebind",
                        "contract": _ADMITTED_RESULT_REBIND_CONTRACT,
                        "project_id": self.project_id,
                        "mission_id": mission_id,
                        "admitted_result": admitted_result,
                        "source_canonical_authority": deep_thaw(source_authority),
                        "source_canonical_authority_digest": (
                            source_canonical_authority_digest
                        ),
                        "target_canonical_authority": deep_thaw(target_authority),
                        "target_canonical_authority_digest": (
                            target_authority_payload.sha256
                        ),
                        "selected_release_sha": selected_release_sha,
                        "predecessor_checkpoint_ref": checkpoint_ref,
                    }
                    authorization_payload = canonical_payload(authorization)
                    current_commit = int(metadata["current_project_commit"])
                    commit_no = current_commit + 1
                    sequence_no = int(
                        connection.execute(
                            "SELECT COALESCE(MAX(sequence_no), 0) + 1 "
                            "FROM transition_journal"
                        ).fetchone()[0]
                    )
                    predecessor_digest = metadata["transition_head_digest"]
                    last_epoch = int(
                        connection.execute(
                            "SELECT COALESCE(MAX(epoch), 0) FROM writer_epoch"
                        ).fetchone()[0]
                    )
                    writer_epoch = last_epoch + 1
                    writer_values = {
                        "epoch": writer_epoch,
                        "project_id": self.project_id,
                        "owner": _ADMITTED_RESULT_REBIND_ACTOR,
                        "lifecycle": "quiesced",
                        "creation_basis": command_id,
                        "predecessor_epoch": last_epoch or None,
                        "takeover_evidence_json": None,
                        "created_at": now,
                        "closed_at": now,
                    }
                    connection.execute(
                        "INSERT INTO writer_epoch("
                        "epoch, project_id, owner, lifecycle, creation_basis, "
                        "predecessor_epoch, takeover_evidence_json, created_at, "
                        "closed_at, row_digest) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                        (
                            *(
                                writer_values[column]
                                for column in _WRITER_DIGEST_COLUMNS
                            ),
                            _writer_digest(writer_values),
                        ),
                    )

                    changed_heads = canonical_payload([])
                    auxiliary_writes = canonical_payload([])
                    evidence_advances = canonical_payload([])
                    dependency_projection: _CurrentDependencyProjection | None = None
                    coverage_commitment: _CaptureCoverageCommitment | None = None
                    if int(metadata["root_digest_version"]) == 6:
                        dependency_projection = _apply_current_dependency_changes(
                            connection,
                            project_id=self.project_id,
                            previous_project_commit=current_commit,
                            current_project_commit=commit_no,
                            changes=_candidate_a1_projection_change(
                                connection,
                                project_id=self.project_id,
                                mission_id=mission_id,
                                remove=candidate_ref,
                            ),
                        )
                        coverage_commitment = _CaptureCoverageMutation(
                            connection,
                            project_id=self.project_id,
                            commitment=_capture_coverage_commitment_at_cut(
                                connection,
                                project_id=self.project_id,
                                project_commit_no=current_commit,
                            ),
                        ).finish(persist=True)
                    inner_result = {
                        "schema_version": (
                            "mathematical_research.admitted_result_rebind_result.v1"
                        ),
                        "mission_id": mission_id,
                        "project_id": self.project_id,
                        "workspace_root": str(self.paths.root),
                        "selected_release_sha": selected_release_sha,
                        "admission_decision_ref": {
                            "id": admission_decision_ref.evidence_id,
                            "digest_sha256": admission_decision_ref.payload_sha256,
                        },
                        "source_canonical_authority_digest": (
                            source_canonical_authority_digest
                        ),
                        "target_canonical_authority_digest": (
                            target_authority_payload.sha256
                        ),
                        "predecessor_checkpoint_ref": checkpoint["checkpoint_id"],
                        "successor_admitted": False,
                    }
                    transition_body = {
                        "sequence_no": sequence_no,
                        "project_id": self.project_id,
                        "project_commit_no": commit_no,
                        "command_id": command_id,
                        "command_kind": _ADMITTED_RESULT_REBIND_COMMAND_KIND,
                        "request_digest": bound_request.sha256,
                        "actor": _ADMITTED_RESULT_REBIND_ACTOR,
                        "writer_epoch": writer_epoch,
                        "changed_heads": [],
                        "auxiliary_writes_digest": auxiliary_writes.sha256,
                        "evidence_head_advances_digest": evidence_advances.sha256,
                        "authorization_digest": authorization_payload.sha256,
                        "canonical_effect": "exact_authorized_delta",
                        "predecessor_digest": predecessor_digest,
                        "created_at": now,
                    }
                    if int(metadata["root_digest_version"]) == 6:
                        transition_body["result_payload_digest"] = canonical_payload(
                            inner_result
                        ).sha256
                        transition_body["changed_head_rows_digest"] = changed_heads.sha256
                        assert dependency_projection is not None
                        transition_body["current_dependency_root_digest"] = (
                            dependency_projection.root_digest
                        )
                        transition_body["current_dependency_entry_count"] = (
                            dependency_projection.entry_count
                        )
                        assert coverage_commitment is not None
                        transition_body["capture_coverage_root_digest"] = (
                            coverage_commitment.root_digest
                        )
                        transition_body["capture_coverage_entry_count"] = (
                            coverage_commitment.entry_count
                        )
                    if int(metadata["schema_version"]) == 12:
                        transition_body["owner_content_index"] = dict(
                            _owner_content_binding_at_cut(
                                connection, project_id=self.project_id,
                                source_project_commit=current_commit,
                            )["owner_content_index"]
                        )
                    transition_digest = _digest(
                        canonical_json_bytes(transition_body)
                    )
                    connection.execute(
                        "INSERT INTO project_commit("
                        "commit_no, project_id, root_digest, canonical_authority_digest, "
                        "transition_head_digest, command_id, created_by, created_at"
                        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                        (
                            commit_no,
                            self.project_id,
                            "0" * 64,
                            target_authority_payload.sha256,
                            transition_digest,
                            command_id,
                            _ADMITTED_RESULT_REBIND_ACTOR,
                            now,
                        ),
                    )
                    root_digest = self._head_root_digest(
                        connection,
                        canonical_authority_digest=target_authority_payload.sha256,
                    )
                    connection.execute(
                        "UPDATE project_commit SET root_digest = ? WHERE commit_no = ?",
                        (root_digest, commit_no),
                    )
                    connection.execute(
                        "INSERT INTO transition_journal("
                        "sequence_no, project_id, project_commit_no, command_id, "
                        "command_kind, request_digest, actor, writer_epoch, "
                        "changed_heads_json, auxiliary_writes_json, "
                        "auxiliary_writes_digest, authorization_json, "
                        "evidence_head_advances_json, evidence_head_advances_digest, "
                        "canonical_effect, predecessor_digest, digest_sha256, created_at"
                        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                        (
                            sequence_no,
                            self.project_id,
                            commit_no,
                            command_id,
                            _ADMITTED_RESULT_REBIND_COMMAND_KIND,
                            bound_request.sha256,
                            _ADMITTED_RESULT_REBIND_ACTOR,
                            writer_epoch,
                            changed_heads.text,
                            auxiliary_writes.text,
                            auxiliary_writes.sha256,
                            authorization_payload.text,
                            evidence_advances.text,
                            evidence_advances.sha256,
                            "exact_authorized_delta",
                            predecessor_digest,
                            transition_digest,
                            now,
                        ),
                    )
                    if int(metadata["root_digest_version"]) == 6:
                        connection.execute(
                            "UPDATE transition_journal SET changed_head_rows_json = ?, "
                            "result_payload_digest = ?, "
                            "current_dependency_root_digest = ?, "
                            "current_dependency_entry_count = ?, "
                            "capture_coverage_root_digest = ?, "
                            "capture_coverage_entry_count = ? WHERE command_id = ?",
                            (
                                changed_heads.text,
                                canonical_payload(inner_result).sha256,
                                dependency_projection.root_digest,
                                dependency_projection.entry_count,
                                coverage_commitment.root_digest,
                                coverage_commitment.entry_count,
                                command_id,
                            ),
                        )
                    if int(metadata["schema_version"]) == 12:
                        connection.execute(
                            "UPDATE transition_journal SET owner_content_index_json = ? WHERE command_id = ?",
                            (canonical_payload(transition_body["owner_content_index"]).text, command_id),
                        )
                    result_payload = canonical_payload(
                        {
                            "result": inner_result,
                            "project_commit": commit_no,
                            "root_digest": root_digest,
                            "transition_digest": transition_digest,
                            "changed_heads": [],
                            "auxiliary_writes_digest": auxiliary_writes.sha256,
                            "evidence_head_advances_digest": (
                                evidence_advances.sha256
                            ),
                            "auxiliary_write_count": 0,
                            "canonical_effect": "exact_authorized_delta",
                        }
                    )
                    self._insert_command_result(
                        connection,
                        command_id=command_id,
                        actor=_ADMITTED_RESULT_REBIND_ACTOR,
                        request_digest=bound_request.sha256,
                        writer_epoch=writer_epoch,
                        result_payload=result_payload,
                        project_commit_no=commit_no,
                        created_at=now,
                    )
                    connection.execute(
                        "UPDATE workspace_metadata SET canonical_authority_json = ?, "
                        "canonical_authority_digest = ?, current_project_commit = ?, "
                        "current_root_digest = ?, transition_head_digest = ?, "
                        "updated_at = ? WHERE singleton = 1",
                        (
                            target_authority_payload.text,
                            target_authority_payload.sha256,
                            commit_no,
                            root_digest,
                            transition_digest,
                            now,
                        ),
                    )
                    persisted_journal = connection.execute(
                        "SELECT * FROM transition_journal WHERE command_id = ?",
                        (command_id,),
                    ).fetchone()
                    if persisted_journal is None:
                        raise WorkspaceIntegrityError(
                            "admitted-result rebind journal was not persisted"
                        )
                    _admitted_result_rebind_authorization(
                        connection,
                        project_id=self.project_id,
                        journal=persisted_journal,
                        expected_source_authority_digest=(
                            source_canonical_authority_digest
                        ),
                        expected_target_authority_digest=(
                            target_authority_payload.sha256
                        ),
                        cas=cas,
                    )
                    if int(metadata["root_digest_version"]) == 6:
                        self._verify_current_boundary(connection)
                    connection.execute("ROLLBACK" if dry_run else "COMMIT")
                    outcome = CommandOutcome(
                        command_id=command_id,
                        writer_epoch=writer_epoch,
                        replayed=False,
                        project_commit=commit_no,
                        root_digest=root_digest,
                        transition_digest=transition_digest,
                        changed_heads=(),
                        result=_object_from_json(result_payload.text),
                    )
            except BaseException:
                if connection.in_transaction:
                    connection.execute("ROLLBACK")
                raise

        stored = outcome.result.get("result")
        if not isinstance(stored, Mapping):
            raise WorkspaceIntegrityError(
                "admitted-result rebind result envelope is invalid"
            )
        return AdmittedResultRebindResult(
            mission_id=str(stored["mission_id"]),
            project_id=str(stored["project_id"]),
            workspace_root=str(stored["workspace_root"]),
            selected_release_sha=str(stored["selected_release_sha"]),
            admission_decision_id=str(stored["admission_decision_ref"]["id"]),
            admission_decision_digest=str(
                stored["admission_decision_ref"]["digest_sha256"]
            ),
            source_canonical_authority_digest=str(
                stored["source_canonical_authority_digest"]
            ),
            target_canonical_authority_digest=str(
                stored["target_canonical_authority_digest"]
            ),
            predecessor_checkpoint_ref=str(
                stored["predecessor_checkpoint_ref"]
            ),
            project_commit=outcome.project_commit,
            root_digest=outcome.root_digest,
            transition_digest=outcome.transition_digest,
            idempotent=outcome.replayed,
            successor_admitted=bool(stored["successor_admitted"]),
        )

    def read_admitted_result(self, mission_id: str) -> Mapping[str, Any] | None:
        """Read canonical RH truth only from the exact current rebind boundary."""

        mission_id = _require_text(mission_id, "mission_id")
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            if int(self._metadata(connection)["root_digest_version"]) == 6:
                self._verify_current_boundary(connection)
            terminal = _current_admitted_result_from_connection(
                connection,
                project_id=self.project_id,
                mission_id=mission_id,
                cas=EvidenceCAS(self.paths),
            )
        return (
            None
            if terminal is None
            else deep_freeze(deep_thaw(terminal["admitted_result"]))
        )

    def read_evidence_meaning_revision(
        self,
        evidence_id: str,
        revision: int | None = None,
        *,
        source_project_commit: int | None = None,
    ) -> Mapping[str, Any]:
        """Read one Evidence meaning and its exact separately journaled sources.

        An optional indexed source cut requires a held direct-read snapshot and
        authenticates the origin internally through the existing schema12
        inventory. Ordinary callers retain their original origin-resolution
        route; neither route skips source, physical-availability or security
        validation, and neither materializes supporting artifact bodies.
        """

        evidence, _page = self._read_evidence_meaning_revision(
            evidence_id, revision, source_project_commit=source_project_commit,
        )
        return evidence

    def read_evidence_source_artifact_page(
        self, *, mission_id: str, evidence_id: str, revision: int,
        expected_payload_digest: str, source_project_commit: int,
        source_ordinal: int, artifact_handle: str,
        offset_bytes: int, max_bytes: int,
    ) -> Mapping[str, Any] | None:
        """Read a bounded range through one exact ordinary Evidence/source relation.

        A held indexed read snapshot is required. The ordinary Evidence reader
        still authenticates every related Blob; its selected Blob verification
        also collects the page. A mismatched relation returns no page only after
        the usual Evidence checks. No result survives this request as authority.
        """
        if type(revision) is not int or revision < 1:
            raise ValueError("source page requires an exact positive Evidence revision")
        if type(source_project_commit) is not int or source_project_commit < 0:
            raise ValueError("source page requires an exact nonnegative source cut")
        if (not isinstance(expected_payload_digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", expected_payload_digest) is None):
            raise ValueError("source page requires an exact Evidence payload digest")
        if any(type(value) is not int or value < 0
               for value in (source_ordinal, offset_bytes)):
            raise ValueError("source page ordinals and offset must be nonnegative")
        if type(max_bytes) is not int or not 1 <= max_bytes <= 65536:
            raise ValueError("source page byte limit must be 1..65536")
        if not isinstance(artifact_handle, str):
            raise ValueError("source page artifact handle must be text")
        selection = _EvidenceSourcePageSelection(
            mission_id=_require_text(mission_id, "mission_id"),
            payload_digest=expected_payload_digest, source_ordinal=source_ordinal,
            artifact_handle=artifact_handle, offset_bytes=offset_bytes,
            max_bytes=max_bytes,
        )
        _evidence, page = self._read_evidence_meaning_revision(
            evidence_id, revision, source_project_commit=source_project_commit,
            source_page=selection,
        )
        return page

    def _read_evidence_meaning_revision(
        self, evidence_id: str, revision: int | None = None, *,
        source_project_commit: int | None = None,
        source_page: _EvidenceSourcePageSelection | None = None,
    ) -> tuple[Mapping[str, Any], Mapping[str, Any] | None]:
        """One Evidence validation path for full meaning and composed source reads."""
        if source_page is not None and type(source_page) is not _EvidenceSourcePageSelection:
            raise TypeError("Evidence source page must be a private exact selection")
        evidence_id = _require_text(evidence_id, "evidence_id")
        if revision is not None and (
            isinstance(revision, bool) or not isinstance(revision, int) or revision < 1
        ):
            raise ValueError("Evidence revision must be positive or None")
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            metadata = self._metadata(connection)
            root_digest_version = int(metadata["root_digest_version"])
            if root_digest_version == 6:
                self._verify_current_boundary(connection)
            head = _validated_evidence_head_from_connection(connection, evidence_id)
            selected_revision = revision
            if selected_revision is None:
                if head is None:
                    raise StaleCommandError(
                        f"Evidence meaning is absent: {evidence_id}"
                    )
                selected_revision = int(head["revision"])
            payload = _successor_evidence_payload_from_connection(
                connection,
                evidence_id=evidence_id,
                revision=selected_revision,
            )
            if payload is None:
                raise StaleCommandError(
                    f"Evidence meaning revision is absent: {evidence_id}@{selected_revision}"
                )
            row = connection.execute(
                "SELECT * FROM evidence_item_revision "
                "WHERE evidence_id = ? AND revision = ?",
                (evidence_id, selected_revision),
            ).fetchone()
            if row is None:
                raise WorkspaceIntegrityError(
                    "Evidence meaning revision disappeared from its read snapshot"
                )
            indexed_origin = None
            if source_project_commit is not None:
                subject = payload["record"].get("subject")
                mission_id = subject.get("mission_id") if isinstance(subject, Mapping) else None
                if not isinstance(mission_id, str) or not mission_id:
                    raise WorkspaceIntegrityError("indexed Evidence has no exact subject Mission")
                indexed = self.read_indexed_observation_owner(
                    mission_id=mission_id, kind="evidence", identity=evidence_id,
                    revision=selected_revision, source_project_commit=source_project_commit,
                )
                if indexed is None:
                    raise StaleCommandError("Evidence revision is not retained at the indexed source cut")
                indexed_origin = int(indexed["project_commit"])
            if root_digest_version == 6:
                _require_historical_evidence_revision_origin(
                    connection,
                    project_id=self.project_id,
                    row=row,
                    indexed_origin_commit=indexed_origin,
                    allow_legacy_fallback=source_project_commit is None,
                )
            elif head is None or selected_revision != int(head["revision"]):
                journal_index = _validated_journal_index(
                    connection,
                    project_id=self.project_id,
                )
                spec = _AUXILIARY_SPECS[
                    AuxiliaryTable.EVIDENCE_ITEM_REVISION
                ]
                origin = _journaled_auxiliary_origin(
                    connection,
                    project_id=self.project_id,
                    table=AuxiliaryTable.EVIDENCE_ITEM_REVISION,
                    row_values={column: row[column] for column in spec.columns},
                    journal_index=journal_index,
                )
                journal = journal_index.journals_by_commit[
                    origin.project_commit_no
                ][0]
                _validated_evidence_payload_from_row(
                    connection,
                    row,
                    journal=journal,
                )
                _require_evidence_source_references(
                    connection,
                    row,
                    journal,
                )
            source_blob_sha256s: set[str] = set()
            capture_ids = tuple(
                str(item["capture_id"])
                for item in payload["sources"]
            )
            captures = _validated_raw_capture_reads_from_connection(
                connection,
                project_id=self.project_id,
                capture_ids=capture_ids,
            )
            subject_mission_id: str | None = None
            if payload["sources"]:
                subject = payload["record"].get("subject")
                selected_mission_id = (
                    subject.get("mission_id")
                    if isinstance(subject, Mapping)
                    else None
                )
                if not isinstance(selected_mission_id, str) or not selected_mission_id:
                    raise WorkspaceIntegrityError(
                        "Evidence meaning with Capture sources lacks its exact "
                        "subject Mission"
                    )
                subject_mission_id = selected_mission_id
            selected_source = None
            selected_range = None
            for source in payload["sources"]:
                capture = captures.get(str(source["capture_id"]))
                if (
                    capture is None
                    or str(capture["record"]["mission_id"])
                    != subject_mission_id
                ):
                    raise WorkspaceIntegrityError(
                        "Evidence meaning Capture crosses its subject Mission"
                    )
                matching_artifacts = (
                    ()
                    if capture is None
                    else tuple(
                        item
                        for item in capture["artifacts"]
                        if int(item["ordinal"])
                        == int(source["artifact_ordinal"])
                    )
                )
                if len(matching_artifacts) != 1:
                    raise WorkspaceIntegrityError(
                        "Evidence meaning capture-source artifact is absent"
                    )
                source_blob_sha256s.add(
                    str(matching_artifacts[0]["blob_sha256"])
                )
                if (source_page is not None
                    and int(source["source_ordinal"]) == source_page.source_ordinal
                    and f"capture-artifact:{source['capture_id']}#{source['artifact_ordinal']}"
                    == source_page.artifact_handle):
                    selected_source = source
                    selected_range = _SelectedBlobRange(
                        str(matching_artifacts[0]["blob_sha256"]),
                        source_page.offset_bytes, source_page.max_bytes,
                    )
            selected_blob_sha256s = tuple(
                sorted(
                    source_blob_sha256s.union(
                        str(item[1])
                        for item in payload["record"]["blob_roles"]
                    )
                )
            )
            selected_bytes = _require_selected_blob_physical_availability(
                connection,
                cas=EvidenceCAS(self.paths),
                blob_sha256s=selected_blob_sha256s,
                label=f"Evidence meaning {evidence_id}@{selected_revision}",
                selected_range=selected_range,
            )
            try:
                _require_ordinary_security_availability(
                    connection,
                    project_id=self.project_id,
                    root_digest_version=root_digest_version,
                    blob_sha256s=selected_blob_sha256s,
                    evidence_references=((evidence_id, selected_revision),),
                )
            except _OrdinarySecurityDispositionError as exc:
                raise StaleCommandError(
                    f"Evidence meaning is security-disposed: "
                    f"{evidence_id}@{selected_revision}"
                ) from exc
            page = None
            if source_page is not None:
                if str(row["payload_digest"]) != source_page.payload_digest:
                    raise WorkspaceIntegrityError("observation Evidence changed its authenticated payload")
                if (payload["record"].get("subtype") != "evidence_meaning"
                    or payload["record"].get("subject", {}).get("mission_id") != source_page.mission_id):
                    raise StaleCommandError("source page requires ordinary Evidence in its exact Mission")
                if selected_source is not None:
                    if selected_bytes is None:
                        raise WorkspaceIntegrityError("source page lost its verified byte selection")
                    verified_record, raw = selected_bytes
                    with self._raw_capture_artifact_read_authority(
                        cas=EvidenceCAS(self.paths), mission_id=source_page.mission_id,
                        capture_id=str(selected_source["capture_id"]),
                        artifact_ordinal=int(selected_source["artifact_ordinal"]),
                    ) as (descriptor, record):
                        if record != verified_record:
                            raise WorkspaceIntegrityError("source page Blob differs from its verified snapshot")
                        if source_page.offset_bytes > record.length:
                            raise ValueError("observation byte offset exceeds exact extent")
                        page = deep_freeze({
                            "descriptor": descriptor, "source": selected_source,
                            "total_bytes": record.length, "content": raw,
                        })
        thawed = deep_thaw(payload)
        thawed["record"]["revision"] = selected_revision
        thawed["payload_digest"] = str(row["payload_digest"])
        thawed["created_at"] = str(row["created_at"])
        return deep_freeze(thawed), page

    def read_candidate_a1_triage_revision(
        self,
        *,
        mission_id: str,
        candidate_id: str,
        candidate_revision: int,
        candidate_digest: str,
    ) -> CandidateA1TriageRecord | None:
        """Read the sole proof-neutral triage finding for one exact Candidate A1."""

        mission_id = _require_text(mission_id, "mission_id")
        candidate_id = _require_text(candidate_id, "candidate_id")
        if (
            isinstance(candidate_revision, bool)
            or not isinstance(candidate_revision, int)
            or candidate_revision < 1
        ):
            raise ValueError("candidate_revision must be positive")
        if (
            not isinstance(candidate_digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", candidate_digest) is None
        ):
            raise ValueError("candidate_digest must be lowercase SHA-256")
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            if int(self._metadata(connection)["root_digest_version"]) == 6:
                self._verify_current_boundary(connection)
            material = _candidate_a1_triage_from_connection(
                connection,
                mission_id=mission_id,
                candidate_id=candidate_id,
                candidate_revision=candidate_revision,
                candidate_digest=candidate_digest,
                cas=EvidenceCAS(self.paths),
            )
        return None if material is None else material[0]

    def list_mission_evidence_meaning_heads(
        self,
        mission_id: str,
    ) -> tuple[Mapping[str, Any], ...]:
        """Enumerate current Evidence-meaning heads belonging to one Mission."""

        mission_id = _require_text(mission_id, "mission_id")
        with self._connection(read_only=True) as connection:
            heads = tuple(
                (str(row["evidence_id"]), int(row["revision"]))
                for row in connection.execute(
                    "SELECT h.evidence_id, h.revision, r.subtype "
                    "FROM evidence_item_head h "
                    "JOIN evidence_item_revision r ON r.evidence_id = h.evidence_id "
                    "AND r.revision = h.revision "
                    "ORDER BY h.evidence_id"
                )
                if not _requires_candidate_a1_evidence_route(
                    evidence_id=str(row["evidence_id"]),
                    subtype=str(row["subtype"]),
                )
            )
        result: list[Mapping[str, Any]] = []
        for evidence_id, revision in heads:
            item = self.read_evidence_meaning_revision(evidence_id, revision)
            subject = item["record"].get("subject")
            if isinstance(subject, Mapping) and subject.get("mission_id") == mission_id:
                result.append(item)
        return tuple(result)

    def commit_capture_scope_annotation_revision(
        self,
        *,
        executive_epoch_id: str,
        annotation_id: str,
        capture_id: str,
        exact_scope: Mapping[str, Any],
        lifecycle: str,
        created_epoch_id: str,
        expected_head_revision: int | None,
        expected_head_payload_digest: str | None,
        dependency_heads: Mapping[str, tuple[int, str]] | None = None,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Revise the optional exact-scope neutral-material resurfacing annotation."""

        annotation_id = _require_text(annotation_id, "annotation_id")
        capture_id = _require_text(capture_id, "capture_id")
        created_epoch_id = _require_text(created_epoch_id, "created_epoch_id")
        if _require_text(executive_epoch_id, "executive_epoch_id") != created_epoch_id:
            raise ValueError(
                "capture annotation created_epoch_id differs from its active Executive Epoch"
            )
        if not isinstance(exact_scope, Mapping) or not exact_scope:
            raise ValueError(
                "capture annotation exact_scope must be a non-empty object"
            )
        if lifecycle not in {"active", "removed"}:
            raise ValueError("capture annotation lifecycle must be active or removed")
        if (expected_head_revision is None) != (expected_head_payload_digest is None):
            raise ValueError(
                "annotation target revision and digest must be supplied together"
            )
        revision = 1 if expected_head_revision is None else expected_head_revision + 1
        semantic_payload = {
            "annotation_id": annotation_id,
            "capture_id": capture_id,
            "exact_scope": deep_thaw(exact_scope),
            "lifecycle": lifecycle,
        }
        payload_digest = canonical_payload(semantic_payload).sha256
        auxiliary = (
            AuxiliaryWrite(
                AuxiliaryTable.CAPTURE_SCOPE_ANNOTATION_REVISION,
                {
                    "annotation_id": annotation_id,
                    "revision": revision,
                    "capture_id": capture_id,
                    "exact_scope_json": exact_scope,
                    "lifecycle": lifecycle,
                    "predecessor_revision": expected_head_revision,
                    "created_actor": actor,
                    "created_epoch_id": created_epoch_id,
                    "payload_digest": payload_digest,
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.CAPTURE_SCOPE_ANNOTATION_HEAD,
                {
                    "annotation_id": annotation_id,
                    "revision": revision,
                    "payload_digest": payload_digest,
                },
            ),
        )
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.CAPTURE,
            lease=lease,
            command_id=command_id,
            actor=actor,
            command_kind="commit_capture_scope_annotation_revision",
            executive_epoch_id=executive_epoch_id,
            request={
                "annotation_id": annotation_id,
                "semantic_payload_digest": payload_digest,
            },
            semantic_payload=semantic_payload,
            auxiliary_writes=auxiliary,
            target_head_key=f"capture_annotation:{annotation_id}",
            expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            dependency_heads=dependency_heads,
            expected_canonical_authority_digest=(expected_canonical_authority_digest),
        )

    def read_capture_scope_annotation(
        self,
        annotation_id: str,
        revision: int | None = None,
    ) -> Mapping[str, Any]:
        """Read one current or historical exact-scope capture annotation."""

        annotation_id = _require_text(annotation_id, "annotation_id")
        with self._connection(read_only=True) as connection:
            if not connection.in_transaction:
                connection.execute("BEGIN")
            head = _successor_head_from_connection(
                connection,
                f"capture_annotation:{annotation_id}",
            )
            selected_revision = revision
            if selected_revision is None:
                if head is None:
                    raise StaleCommandError(
                        f"capture annotation is absent: {annotation_id}"
                    )
                selected_revision = head[0]
            if (
                isinstance(selected_revision, bool)
                or not isinstance(selected_revision, int)
                or selected_revision < 1
            ):
                raise ValueError("annotation revision must be positive or None")
            row = connection.execute(
                "SELECT * FROM capture_scope_annotation_revision "
                "WHERE annotation_id = ? AND revision = ?",
                (annotation_id, selected_revision),
            ).fetchone()
            if row is None:
                raise StaleCommandError(
                    f"capture annotation revision is absent: {annotation_id}@{selected_revision}"
                )
            payload, _capture, _origin_commit = _require_exact_annotation_dependency(
                connection,
                project_id=self.project_id,
                row=row,
            )
        return deep_freeze(
            {
                **deep_thaw(payload),
                "revision": selected_revision,
                "annotation_kind": str(row["annotation_kind"]),
                "created_actor": str(row["created_actor"]),
                "created_epoch_id": str(row["created_epoch_id"]),
                "created_at": str(row["created_at"]),
                "payload_digest": str(row["payload_digest"]),
            }
        )

    def list_mission_capture_scope_annotation_heads(
        self,
        mission_id: str,
    ) -> tuple[Mapping[str, Any], ...]:
        """Enumerate current capture-scope annotations for one Mission."""

        mission_id = _require_text(mission_id, "mission_id")
        with self._connection(read_only=True) as connection:
            annotation_ids = tuple(
                str(row["annotation_id"])
                for row in connection.execute(
                    "SELECT annotation_id FROM capture_scope_annotation_head "
                    "ORDER BY annotation_id"
                )
            )
        result: list[Mapping[str, Any]] = []
        for annotation_id in annotation_ids:
            annotation = self.read_capture_scope_annotation(annotation_id)
            capture = self.read_raw_capture(str(annotation["capture_id"]))
            if str(capture["record"]["mission_id"]) == mission_id:
                result.append(annotation)
        return tuple(result)

    def commit_scientific_context_publication(
        self, *, executive_epoch_id: str, mission_id: str,
        updates: Sequence[Any], exposure_required: Sequence[Mapping[str, Any]],
        evidence: Any = None, request_sha256: str,
        lease: WriterLease, command_id: str, actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Publish explicit scientific meaning using the existing sole writer.

        The compact result binding uses the existing journal/result owner; it
        is not a pending-publication record or an incorporation ledger. Even
        an all-member no-op journals its acknowledgement for exact replay,
        without manufacturing another Context or Evidence revision.
        """
        from .context_revision import PreparedScientificContextUpdate
        from .mission_evidence import EvidenceMeaningRecord, read_evidence_meaning

        if not updates or any(type(item) is not PreparedScientificContextUpdate for item in updates):
            raise ValueError("scientific publication requires prepared Context members")
        if re.fullmatch(r"[0-9a-f]{64}", request_sha256) is None:
            raise ValueError("scientific request binding must be SHA-256")
        contexts: list[dict[str, Any]] = []
        writes: list[RevisionWrite] = []
        dependencies: dict[str, tuple[int, str]] = {}
        references: list[Mapping[str, Any]] = []
        changed_treatments: list[Mapping[str, Any]] = []
        for item in updates:
            item.record.verify_issued()
            document = deep_thaw(item.record.document)
            context_id = str(document["context_id"])
            if document["project_id"] != self.project_id or document["mission_id"] != mission_id:
                raise ValueError("scientific member belongs to another project or Mission")
            if context_id in {member["context_id"] for member in contexts}:
                raise ValueError("scientific publication repeats a Context")
            previous = item.expected_head
            previous_revision = None if previous is None else int(previous["revision"])
            revision = (1 if previous_revision is None else previous_revision + 1) if item.changed else previous_revision
            if revision is None:
                raise ValueError("absent Context cannot be an unchanged member")
            reference = {"kind": "context", "identity": context_id, "revision": revision,
                         "payload_sha256": item.record.digest_sha256}
            removed: list[str] = []
            if previous is not None:
                before = self.read_context_revision(context_id, previous_revision)
                if before["payload_digest"] != previous["payload_sha256"]:
                    raise StaleCommandError("scientific Context frozen preimage digest differs")
                removed = sorted(set(before["payload"].get("treatments", {})) - set(document["treatments"]))
            contexts.append({"context_id": context_id, "expected_head": deep_thaw(previous),
                             "payload": document, "changed_treatment_ids": list(item.changed_treatment_ids),
                             "removed_treatment_ids": removed, "changed": item.changed})
            references.append(reference)
            for key in (*item.changed_treatment_ids, *removed):
                changed_treatments.append({"context_reference": reference, "treatment_id": key})
            if item.changed:
                writes.append(RevisionWrite(object_id=TypedWorkspaceId(IdentityKind.CONTEXT, context_id),
                                            payload=document, expected_revision=previous_revision))
            for key, value in item.dependency_heads.items():
                normalized = (int(value[0]), str(value[1]))
                if key in dependencies and dependencies[key] != normalized:
                    raise ValueError("scientific publication has conflicting current-sensitive guards")
                dependencies[key] = normalized
        evidence_member = None
        evidence_reference = None
        auxiliary: tuple[AuxiliaryWrite, ...] = ()
        advances: tuple[EvidenceHeadAdvance, ...] = ()
        if evidence is not None:
            if type(evidence) is not EvidenceMeaningRecord:
                raise TypeError("paired publication requires prepared ordinary Evidence meaning")
            evidence.verify_prepared()
            if evidence._authority is None or evidence._authority.executive_epoch_id != executive_epoch_id:
                raise ValueError("paired Evidence authority differs from publication Epoch")
            meaning, evidence_auxiliary, advance = self._prepare_evidence_meaning_projection(
                record=evidence.evidence,
                sources=tuple(value.to_payload(index) for index, value in enumerate(evidence.sources)),
                interpreted_inputs=tuple(value.to_payload() for value in evidence.interpreted_inputs),
                expected_head_revision=evidence.expected_head_revision,
                expected_head_payload_digest=evidence.expected_head_payload_digest,
            )
            changed = True
            if evidence.expected_head_revision is not None:
                prior = read_evidence_meaning(self, evidence_id=evidence.evidence_id,
                                              revision=evidence.expected_head_revision)
                if prior.payload_digest != evidence.expected_head_payload_digest:
                    raise StaleCommandError("paired Evidence frozen preimage digest differs")
                prior_record = deep_thaw(prior.evidence.to_payload())
                prior_record.pop("revision")
                changed = not (
                    canonical_json_bytes(prior_record) == canonical_json_bytes(meaning["record"])
                    and prior.sources == evidence.sources and prior.interpreted_inputs == evidence.interpreted_inputs
                )
            evidence_reference = {
                "kind": "evidence", "identity": evidence.evidence_id,
                "revision": evidence.revision if changed else evidence.expected_head_revision,
                "payload_sha256": advance.target_payload_digest if changed else evidence.expected_head_payload_digest,
            }
            evidence_member = {**deep_thaw(meaning), "expected_head": None if evidence.expected_head_revision is None else {
                "kind": "evidence", "identity": evidence.evidence_id,
                "revision": evidence.expected_head_revision, "payload_sha256": evidence.expected_head_payload_digest,
            }, "reference": evidence_reference, "changed": changed}
            if changed:
                auxiliary, advances = evidence_auxiliary, (advance,)
            for key, value in evidence.expected_dependency_heads.items():
                normalized = (int(value[0]), str(value[1]))
                if key in dependencies and dependencies[key] != normalized:
                    raise ValueError("paired Evidence conflicts with an explicit Context dependency")
                dependencies[key] = normalized
        semantic = {"mission_id": mission_id, "contexts": contexts, "evidence": evidence_member,
                    "exposure_required": deep_thaw(exposure_required),
                    "semantic_noop": not writes and not auxiliary}
        receipt = _scientific_receipt_from_semantic(semantic, request_sha256=request_sha256)
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.CONTEXT, lease=lease, command_id=command_id,
            actor=actor, command_kind="commit_scientific_context_publication",
            executive_epoch_id=executive_epoch_id, request={"request_sha256": request_sha256, "publication": semantic},
            semantic_payload=semantic, writes=tuple(writes), auxiliary_writes=auxiliary,
            evidence_head_advances=advances, dependency_heads=dependencies,
            expected_canonical_authority_digest=expected_canonical_authority_digest,
            scientific_publication_receipt=receipt,
        )

    def read_scientific_publication_result(
        self, *, mission_id: str, command_id: str,
        request_sha256: str | None = None, replayed: bool = True,
    ) -> Mapping[str, Any] | None:
        """Authenticate original publication refs, never resolve today's heads."""
        with self._connection(read_only=True) as connection:
            row = connection.execute("SELECT * FROM command_result WHERE command_id = ?", (command_id,)).fetchone()
            if row is None:
                return None
            journal = _validated_commit_envelope(connection, project_id=self.project_id,
                                                commit_no=int(row["project_commit_no"]))
            if journal is None or journal.row["command_kind"] != "commit_scientific_context_publication":
                raise CommandConflictError("command identity is not a scientific publication")
            if _digest(str(row["result_json"]).encode("utf-8")) != row["result_digest"]:
                raise WorkspaceIntegrityError("scientific publication result is corrupt")
            result = _object_from_json(str(row["result_json"]))
            receipt = result.get("result", {}).get("scientific_publication")
            if not isinstance(receipt, Mapping) or receipt.get("mission_id") != mission_id:
                raise StaleCommandError("scientific publication is outside this Mission")
            if request_sha256 is not None and receipt.get("request_sha256") != request_sha256:
                raise CommandConflictError("scientific publication request differs from the original")
            return _scientific_publication_result_from_receipt(
                self, connection, receipt=receipt, command_id=command_id,
                project_commit=int(row["project_commit_no"]), replayed=replayed,
            )

    def commit_context_revision(
        self,
        *,
        executive_epoch_id: str,
        context_id: str,
        payload: Mapping[str, Any],
        expected_head_revision: int | None,
        expected_head_payload_digest: str | None,
        dependency_heads: Mapping[str, tuple[int, str]] | None = None,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Commit one first-class Context revision with only adopted head dependencies."""

        context_id = _require_text(context_id, "context_id")
        if not isinstance(payload, Mapping) or not payload:
            raise ValueError("Context payload must be a non-empty semantic object")
        if (expected_head_revision is None) != (expected_head_payload_digest is None):
            raise ValueError(
                "Context target revision and digest must be supplied together"
            )
        write = RevisionWrite(
            object_id=TypedWorkspaceId(IdentityKind.CONTEXT, context_id),
            payload=payload,
            expected_revision=expected_head_revision,
        )
        semantic_payload = deep_thaw(payload)
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.CONTEXT,
            lease=lease,
            command_id=command_id,
            actor=actor,
            command_kind="commit_context_revision",
            executive_epoch_id=executive_epoch_id,
            request={
                "context_id": context_id,
                "semantic_payload_digest": canonical_payload(semantic_payload).sha256,
            },
            semantic_payload=semantic_payload,
            writes=(write,),
            target_head_key=write.object_id.key,
            expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            dependency_heads=dependency_heads,
            expected_canonical_authority_digest=(expected_canonical_authority_digest),
        )

    def read_context_revision(
        self,
        context_id: str,
        revision: int | None = None,
    ) -> Mapping[str, Any]:
        """Read one current or historical first-class Context revision."""

        object_id = TypedWorkspaceId(IdentityKind.CONTEXT, context_id)
        stored = (
            self.get_head(object_id)
            if revision is None
            else self.get_revision(RevisionRef(object_id, revision))
        )
        if stored is None:
            suffix = "" if revision is None else f"@{revision}"
            raise StaleCommandError(f"Context revision is absent: {context_id}{suffix}")
        return deep_freeze(
            {
                "context_id": context_id,
                "revision": stored.reference.revision,
                "payload": stored.payload,
                "payload_digest": stored.payload_digest,
                "predecessor_revision": stored.predecessor_revision,
                "created_actor": stored.created_actor,
                "created_at": stored.created_at,
            }
        )

    def list_mission_context_heads(
        self,
        mission_id: str,
    ) -> tuple[Mapping[str, Any], ...]:
        """Enumerate current first-class Context heads belonging to one Mission."""

        mission_id = _require_text(mission_id, "mission_id")
        with self._connection(read_only=True) as connection:
            context_ids = tuple(
                str(row["object_id"])
                for row in connection.execute(
                    "SELECT object_id FROM context_head ORDER BY object_id"
                )
            )
        result: list[Mapping[str, Any]] = []
        for context_id in context_ids:
            item = self.read_context_revision(context_id)
            if item["payload"].get("mission_id") == mission_id:
                result.append(item)
        return tuple(result)

    def read_current_mission_unresolved_owner_facts(
        self,
        mission_id: str,
    ) -> tuple[Mapping[str, Any], ...]:
        """Read explicit unresolved fields from exact current Candidate/Context heads.

        This is the checkpoint writer's current-state projection.  It is valid
        only inside the already-held checkpoint transaction and walks current
        head keys in fixed-size index pages; it never traverses retained owner
        revisions or creates a second unresolved-state authority.
        """

        mission_id = _require_text(mission_id, "mission_id")
        checkpoint_connection = self._checkpoint_write_connection.get()
        if checkpoint_connection is None:
            raise WorkspaceIntegrityError(
                "unresolved checkpoint facts require the active checkpoint write scope"
            )
        with self._connection(read_only=True) as connection:
            if connection is not checkpoint_connection:
                raise WorkspaceIntegrityError(
                    "unresolved checkpoint facts escaped the checkpoint transaction"
                )
            return _current_mission_unresolved_owner_facts_from_connection(
                connection,
                mission_id=mission_id,
            )

    def _commit_successor_direct_owner_revision(
        self,
        *,
        executive_epoch_id: str,
        kind: IdentityKind,
        mission_id: str,
        identity: str,
        payload: Mapping[str, Any],
        expected_head_revision: int | None,
        expected_head_payload_digest: str | None,
        dependency_heads: Mapping[str, tuple[int, str]] | None,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
        request_extension: Mapping[str, Any] | None = None,
        auxiliary_writes: Sequence[AuxiliaryWrite] = (),
        evidence_head_advances: Sequence[EvidenceHeadAdvance] = (),
    ) -> CommandOutcome:
        family, command_kind, identity_field = _SUCCESSOR_DIRECT_OWNER_SPECS[kind]
        mission_id = _require_text(mission_id, "mission_id")
        identity = _require_text(identity, identity_field)
        if not isinstance(payload, Mapping) or not payload:
            raise ValueError(
                f"{kind.value.title()} payload must be a non-empty semantic object"
            )
        semantic_payload = deep_thaw(payload)
        if semantic_payload.get("mission_id") != mission_id:
            raise ValueError(
                f"{kind.value.title()} payload mission_id differs from its Mission query"
            )
        if semantic_payload.get(identity_field) != identity:
            raise ValueError(
                f"{kind.value.title()} payload {identity_field} differs from its owner identity"
            )
        if (expected_head_revision is None) != (expected_head_payload_digest is None):
            raise ValueError(
                f"{kind.value.title()} target revision and digest must be supplied together"
            )
        write = RevisionWrite(
            object_id=TypedWorkspaceId(kind, identity),
            payload=semantic_payload,
            expected_revision=expected_head_revision,
        )
        request = {
            "mission_id": mission_id,
            identity_field: identity,
            "semantic_payload_digest": canonical_payload(semantic_payload).sha256,
        }
        if request_extension is not None:
            request.update(deep_thaw(request_extension))
        return self._apply_successor_storage_command(
            family=family,
            lease=lease,
            command_id=command_id,
            actor=actor,
            command_kind=command_kind,
            executive_epoch_id=executive_epoch_id,
            request=request,
            semantic_payload=semantic_payload,
            writes=(write,),
            auxiliary_writes=auxiliary_writes,
            evidence_head_advances=evidence_head_advances,
            target_head_key=write.object_id.key,
            expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            dependency_heads=dependency_heads,
            expected_canonical_authority_digest=(expected_canonical_authority_digest),
        )

    def _prepare_successor_candidate_a1_projection(
        self,
        *,
        candidate_id: str,
        candidate_payload: Mapping[str, Any],
        candidate_digest: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> tuple[tuple[AuxiliaryWrite, ...], tuple[EvidenceHeadAdvance, ...]]:
        """Install bytes and prepare the exact preservation-first A1 projection."""

        from .evidence_store import (
            ClosureMember,
            ClosureReference,
            build_closure_manifest,
        )

        candidate_bytes = canonical_json_bytes(candidate_payload)
        if _digest(candidate_bytes) != candidate_digest:
            raise WorkspaceIntegrityError(
                "Candidate canonical bytes changed before atomic A1 preparation"
            )
        metadata = self.read_metadata()
        if not is_direct_mission_generation(
            int(metadata["schema_version"]),
            int(metadata["root_digest_version"]),
            str(metadata["operating_mode"]),
        ):
            raise WorkspaceIntegrityError(
                "atomic direct-owner Candidate A1 requires a supported direct Mission store"
            )
        if (
            str(metadata["canonical_authority_digest"])
            != expected_canonical_authority_digest
        ):
            raise StaleCommandError(
                "Candidate A1 canonical authority is stale before CAS installation"
            )

        claimed_scope = ("claim.rh.complete",)
        package_body = {
            "kind": "purported_complete_route_package",
            "project_id": self.project_id,
            "canonical_authority_digest": expected_canonical_authority_digest,
            "artifact_digest": candidate_digest,
            "artifact_byte_length": len(candidate_bytes),
            "media_type": "application/octet-stream",
            "claimed_scope": list(claimed_scope),
            "candidate_id": candidate_id,
            "uncertainty_code": "unverified_candidate",
            "security_classification": "sensitive",
            "packaging_validated": True,
            "truth_validated": False,
            "canonical_effect": "none",
        }
        package_digest = _digest(canonical_json_bytes(package_body))
        ids = _candidate_a1_route_ids(package_digest)
        evidence_subject = {
            "kind": "purported_complete_route",
            "package_digest": package_digest,
            "intake_id": ids.intake_id,
            "candidate_id": candidate_id,
            "claimed_scope": list(claimed_scope),
            "artifact_digest": candidate_digest,
            "expected_alert_id": ids.alert_id,
            "expected_hold_id": ids.hold_id,
            "expected_delivery_intent_id": ids.delivery_intent_id,
        }

        cas = EvidenceCAS(self.paths)
        installed = cas.ingest_bytes(
            candidate_bytes,
            original_name=f"{candidate_id}.json",
            media_type="application/octet-stream",
            encoding=None,
        )
        with self._connection(read_only=True) as connection:
            existing_blob = connection.execute(
                "SELECT first_verified_at, last_verified_at FROM blob WHERE sha256 = ?",
                (candidate_digest,),
            ).fetchone()
        first_verified_at = (
            str(existing_blob["first_verified_at"])
            if existing_blob is not None
            else installed.record.first_verified_at
        )
        last_verified_at = (
            str(existing_blob["last_verified_at"])
            if existing_blob is not None
            else installed.record.last_verified_at
        )
        blob = BlobRecord(
            sha256=installed.record.sha256,
            length=installed.record.length,
            media_type=installed.record.media_type,
            encoding=installed.record.encoding,
            logical_path=installed.record.logical_path,
            integrity_state="verified",
            availability_state="verified_available",
            quarantine_state="clear",
            first_verified_at=first_verified_at,
            last_verified_at=last_verified_at,
        )
        evidence = EvidenceItemRevision(
            evidence_id=ids.evidence_id,
            revision=1,
            subtype="purported_complete_route",
            subject=evidence_subject,
            exact_scope="unverified purported-complete Candidate preservation",
            rigor="unverified_claim",
            limitations=("not independently admitted",),
            non_inferences=("does not establish or canonically admit RH",),
            security_classification="sensitive",
            retention="retain",
            blob_roles=((_PURPORTED_COMPLETE_ARTIFACT_ROLE, blob.sha256),),
            availability_state="verified_available",
        )
        evidence_digest = _digest(canonical_json_bytes(evidence.to_payload()))
        provenance_id = f"provenance:purported-complete:{package_digest}"
        provenance = {
            "provenance_id": provenance_id,
            "evidence_id": evidence.evidence_id,
            "evidence_revision": 1,
            "origin": {
                "source": (
                    f"issued_candidate_revision_v{candidate_payload['schema_version']}"
                )
            },
            "activity": {"kind": "preserve_before_atomic_a1"},
            "agent": {"id": actor},
            "tool": {"id": "workspace-store"},
            "input": {"digest": candidate_digest},
            "transformation": {"kind": "canonical_json_bytes"},
            "custody": {"state": "sealed"},
        }
        disclosure_id = f"independence:purported-complete:{package_digest}"
        disclosure = {
            "disclosure_id": disclosure_id,
            "evidence_id": evidence.evidence_id,
            "evidence_revision": 1,
            "model": {"model": "candidate-author"},
            "exposure": {"context": "producing-executive-epoch"},
            "method": {"method": "exact-candidate-preservation"},
            "sources": [],
            "implementation": {"shared": True},
            "environment": {"kind": "mission-workspace"},
            "correlation": {"known": ["candidate-author"]},
        }
        dependency_id = f"dependency:purported-complete:{package_digest}"
        members = (
            ClosureMember(
                "evidence",
                evidence.evidence_id,
                1,
                evidence_digest,
                references=(
                    ClosureReference("blob", "blob", blob.sha256),
                    ClosureReference("provenance", "provenance", provenance_id, 1),
                    ClosureReference(
                        "independence_disclosure",
                        "independence_disclosure",
                        disclosure_id,
                        1,
                    ),
                    ClosureReference("dependency", "dependency", dependency_id, 1),
                ),
            ),
            ClosureMember("blob", blob.sha256, None, blob.sha256),
            ClosureMember(
                "provenance",
                provenance_id,
                1,
                _digest(canonical_json_bytes(provenance)),
            ),
            ClosureMember(
                "independence_disclosure",
                disclosure_id,
                1,
                _digest(canonical_json_bytes(disclosure)),
            ),
            ClosureMember(
                "dependency",
                dependency_id,
                1,
                _digest(dependency_id.encode("utf-8")),
            ),
        )
        closure = build_closure_manifest(
            closure_id=ids.closure_id,
            root=ClosureReference("evidence", "evidence", evidence.evidence_id, 1),
            members=members,
            blobs={blob.sha256: blob},
            cas=cas,
            canonical_pre_state=loads_strict_json_object(
                str(metadata["canonical_authority_json"])
            ),
        )

        scope = tuple(
            sorted(
                {
                    ids.intake_id,
                    ids.evidence_id,
                    *claimed_scope,
                    candidate_id,
                }
            )
        )

        auxiliary_writes = (
            AuxiliaryWrite(
                AuxiliaryTable.BLOB,
                {
                    "sha256": blob.sha256,
                    "byte_length": blob.length,
                    "media_type": blob.media_type,
                    "encoding": blob.encoding,
                    "integrity_state": "verified",
                    "availability_state": "verified_available",
                    "logical_cas_path": blob.logical_path,
                    "first_verified_at": blob.first_verified_at,
                    "last_verified_at": blob.last_verified_at,
                    "quarantine_state": "clear",
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.EVIDENCE_ITEM_REVISION,
                {
                    "evidence_id": evidence.evidence_id,
                    "revision": 1,
                    "subtype": evidence.subtype,
                    "subject_json": dict(evidence.subject),
                    "exact_scope_json": {"scope": evidence.exact_scope},
                    "rigor": evidence.rigor,
                    "limitations_json": list(evidence.limitations),
                    "non_inferences_json": list(evidence.non_inferences),
                    "security_json": {
                        "classification": evidence.security_classification
                    },
                    "retention_json": {"policy": evidence.retention},
                    "availability_state": "verified_available",
                    "payload_digest": evidence_digest,
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.EVIDENCE_BLOB,
                {
                    "evidence_id": evidence.evidence_id,
                    "evidence_revision": 1,
                    "ordinal": 0,
                    "role": _PURPORTED_COMPLETE_ARTIFACT_ROLE,
                    "blob_sha256": blob.sha256,
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.PROVENANCE_EVENT,
                {
                    "provenance_id": provenance_id,
                    "evidence_id": evidence.evidence_id,
                    "evidence_revision": 1,
                    **{
                        f"{key}_json": value
                        for key, value in provenance.items()
                        if key
                        not in {
                            "provenance_id",
                            "evidence_id",
                            "evidence_revision",
                        }
                    },
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.INDEPENDENCE_DISCLOSURE,
                {
                    "disclosure_id": disclosure_id,
                    "evidence_id": evidence.evidence_id,
                    "evidence_revision": 1,
                    **{
                        f"{key}_json": value
                        for key, value in disclosure.items()
                        if key
                        not in {
                            "disclosure_id",
                            "evidence_id",
                            "evidence_revision",
                        }
                    },
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.CLOSURE_MANIFEST,
                {
                    "closure_id": closure.closure_id,
                    "root_kind": closure.root.target_kind,
                    "root_digest": closure.manifest_sha256,
                    "members_json": [member.to_payload() for member in closure.members],
                    "contract_json": closure.to_payload(),
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.ALERT_EVENT,
                {
                    "alert_id": ids.alert_id,
                    "severity": "A1",
                    "summary_json": {
                        "summary_code": "candidate_review_required",
                        "trigger_digest": package_digest,
                        "closure_digest": closure.manifest_sha256,
                    },
                },
            ),
            *(
                AuxiliaryWrite(
                    AuxiliaryTable.ALERT_SCOPE,
                    {
                        "alert_id": ids.alert_id,
                        "ordinal": ordinal,
                        "scope_kind": "typed_reference",
                        "scope_id": scope_id,
                    },
                )
                for ordinal, scope_id in enumerate(scope)
            ),
            AuxiliaryWrite(
                AuxiliaryTable.ALERT_DELIVERY_INTENT,
                {
                    "delivery_intent_id": ids.delivery_intent_id,
                    "alert_id": ids.alert_id,
                    "transport_kind": "task_only",
                },
            ),
            AuxiliaryWrite(
                AuxiliaryTable.HOLD,
                {
                    "hold_id": ids.hold_id,
                    "alert_id": ids.alert_id,
                    "exact_scope_json": list(scope),
                    "lifecycle": "open",
                },
            ),
        )
        return (
            auxiliary_writes,
            (
                EvidenceHeadAdvance(
                    evidence.evidence_id,
                    1,
                    evidence_digest,
                ),
            ),
        )

    def _owner_mission_replay_preserves_historical_shape(
        self, *, command_id: str, command_kind: str,
        object_id: TypedWorkspaceId, expected_head_revision: int,
    ) -> bool:
        """Choose old serialization only from an authenticated existing effect.

        This does not return or authorize replay. The ordinary sole transaction
        still authenticates the complete reconstructed command envelope. New
        commands can never acquire historical-shape write authority here.
        """
        with self.snapshot_connection() as connection:
            prior = connection.execute(
                "SELECT j.command_kind, j.changed_heads_json, r.project_commit_no "
                "FROM transition_journal j JOIN command_result r "
                "ON r.command_id = j.command_id WHERE j.command_id = ?",
                (command_id,),
            ).fetchone()
            if prior is None:
                return False
            _validated_commit_envelope(
                connection, project_id=self.project_id,
                commit_no=int(prior["project_commit_no"]),
            )
            expected_effect = RevisionRef(object_id, expected_head_revision + 1)
            changed = loads_strict_json_object(
                '{"items":' + str(prior["changed_heads_json"]) + '}'
            )["items"]
            if prior["command_kind"] != command_kind or changed != [expected_effect.key]:
                return False
            retained = connection.execute(
                "SELECT payload_json, payload_digest FROM mission_revision "
                "WHERE object_id = ? AND revision = ?",
                (object_id.value, expected_effect.revision),
            ).fetchone()
            if retained is None:
                raise WorkspaceIntegrityError("retained owner Mission replay effect is absent")
            payload = loads_strict_json_object(str(retained["payload_json"]))
            if canonical_payload(payload).sha256 != retained["payload_digest"]:
                raise WorkspaceIntegrityError("retained owner Mission replay effect is corrupt")
            return "scientific_context_id" not in payload

    def validate_scientific_context_initialization(
        self, *, mission_id: str, expected_head_revision: int,
        expected_head_payload_digest: str, context_document: Mapping[str, Any],
        expected_store_cut: Mapping[str, Any], expected_canonical_authority_digest: str,
        principal_attestation: PrincipalAttestation,
        _connection_override: sqlite3.Connection | None = None,
    ) -> Mapping[str, Any]:
        """Read-only initial-Context preflight, including an owner-authenticated DELETE snapshot.

        The private override must be an already-open read-only snapshot. It does
        not authorize writing, claim custody, close rollback or reserve this cut.
        The committing owner repeats every guard in its own transaction.
        """
        from .context_revision import _record_from_document, _scientific_context_dependency_heads
        from .mission_owner import direct_mission_scientific_context_successor

        cut = _validated_mission_host_store_cut(expected_store_cut)
        if cut["canonical_authority_digest"] != expected_canonical_authority_digest:
            raise ValueError("initialization canonical authority differs from Store cut")
        owner = stable_principal_owner_binding(principal_attestation)
        record = _record_from_document(context_document)
        document = record.document
        if (document["schema_version"] != 3 or document["project_id"] != self.project_id
            or document["mission_id"] != mission_id):
            raise ValueError("initial scientific Context must be exact same-scope v3")
        mission_object = TypedWorkspaceId(IdentityKind.MISSION, mission_id)
        context_object = TypedWorkspaceId(IdentityKind.CONTEXT, document["context_id"])
        scope = nullcontext(_connection_override) if _connection_override is not None else self._connection(read_only=True)
        with scope as connection:
            if not getattr(connection, "_workspace_read_only_snapshot", False):
                raise WorkspaceIntegrityError("initialization preflight requires a read-only snapshot")
            databases = tuple(connection.execute("PRAGMA database_list"))
            main = [row for row in databases if row[1] == "main"]
            if (len(main) != 1 or Path(str(main[0][2])).resolve(strict=True) != self.paths.database.resolve(strict=True)
                or any(row[1] not in {"main", "temp"} for row in databases)):
                raise WorkspaceIntegrityError("initialization snapshot differs from its owner database")
            own_snapshot = not connection.in_transaction
            if own_snapshot:
                connection.execute("BEGIN")
            schema_token = None
            try:
                self.paths.revalidate_physical(require_root=True, require_database=True)
                schema = verify_schema_contract(
                    connection, schema_version=int(connection.execute("PRAGMA user_version").fetchone()[0]),
                    allow_sealed_delete=str(connection.execute("PRAGMA journal_mode").fetchone()[0]).casefold() == "delete",
                )
                schema_token = _ACTIVE_SEALED_READ_SCHEMA.set((connection, self.project_id, schema))
                self._verify_current_boundary(connection, schema=schema)
                metadata = self._metadata(connection)
                _require_mission_host_store_cut(metadata, cut)
                tail = _validated_writer_epoch_tail(connection, project_id=self.project_id)
                if (int(metadata["schema_version"]) != 12 or int(metadata["root_digest_version"]) != 6
                    or metadata["lifecycle"] != "quiesced" or metadata["current_writer_epoch"] is not None
                    or not _scientific_initialization_same_principal_custody(
                        connection, project_id=self.project_id, writer=tail, owner=owner, cut=cut,
                    )):
                    raise StaleWriterError("initialization preflight requires schema12/root6 and the same quiesced principal")
                before = connection.execute("SELECT payload_json, payload_digest FROM mission_revision WHERE object_id = ? AND revision = ?",
                                            (mission_id, expected_head_revision)).fetchone()
                if before is None or before["payload_digest"] != expected_head_payload_digest:
                    raise StaleCommandError("initialization Mission preimage is absent or changed")
                after = direct_mission_scientific_context_successor(
                    loads_strict_json_object(str(before["payload_json"])), context_id=context_object.value,
                )
                semantic = {"mission_id": mission_id, "mission": after, "context": document,
                            "expected_store_cut": cut, "writer_owner": owner,
                            "writer_creation_basis": "initial-scientific-context-read-only-preflight"}
                writes = (RevisionWrite(object_id=mission_object, payload=after, expected_revision=expected_head_revision),
                          RevisionWrite(object_id=context_object, payload=document, expected_revision=None))
                source = _SuccessorStorageCommandSource(
                    family=RevisionCommandFamily.MISSION, command_kind=_SCIENTIFIC_INITIALIZATION_COMMAND_KIND,
                    request_digest=canonical_payload({"initialization": semantic}).sha256,
                    projection_digest=_successor_projection_digest(writes, (), ()), semantic_payload=semantic,
                    executive_epoch_id=None, target_head_key=mission_object.key,
                    expected_target_revision=expected_head_revision, expected_target_payload_digest=expected_head_payload_digest,
                    dependency_heads=_normalize_successor_dependency_heads(_scientific_context_dependency_heads(document, tuple(document["treatments"]))),
                )
                _validate_scientific_initialization_source(connection, project_id=self.project_id,
                    source=source, commit_no=int(cut["project_commit"]) + 1, require_current=True)
                for key, revision, digest in source.dependency_heads:
                    if _successor_head_from_connection(connection, key) != (revision, digest):
                        raise StaleCommandError("initialization current-sensitive source is stale")
                _validate_scientific_publication_transaction(self, connection, source)
                return {"schema_version": "mathematical_research.mission_scientific_context_initialization_validation.v1",
                        "context_payload_sha256": record.digest_sha256, "expected_store_cut": deep_thaw(cut),
                        "writer_owner": owner, "writes": False}
            finally:
                if schema_token is not None:
                    _ACTIVE_SEALED_READ_SCHEMA.reset(schema_token)
                if own_snapshot and connection.in_transaction:
                    connection.execute("ROLLBACK")

    def initialize_mission_scientific_context(
        self, *, mission_id: str, expected_head_revision: int,
        expected_head_payload_digest: str, context_document: Mapping[str, Any],
        expected_store_cut: Mapping[str, Any], expected_canonical_authority_digest: str,
        principal_attestation: PrincipalAttestation, command_id: str, actor: str,
    ) -> CommandOutcome:
        """Create only the explicitly supplied first scientific Context while stopped.

        Host owns rollback closure/containment. This owner requires an unbound
        Mission, no live Epoch, and a quiesced same-principal writer. Claim,
        Context, Mission binding and release commit together; exact replay never
        claims a writer again. No content is generated or legacy Context converted.
        """
        from .context_revision import _record_from_document, _scientific_context_dependency_heads
        from .mission_owner import direct_mission_scientific_context_successor

        owner = stable_principal_owner_binding(principal_attestation)
        cut = _validated_mission_host_store_cut(expected_store_cut)
        if cut["canonical_authority_digest"] != expected_canonical_authority_digest:
            raise ValueError("initialization canonical authority differs from expected Store cut")
        mission_object = TypedWorkspaceId(IdentityKind.MISSION, mission_id)
        before = self.get_revision(RevisionRef(mission_object, expected_head_revision))
        if before is None or before.payload_digest != expected_head_payload_digest:
            raise StaleCommandError("scientific initialization Mission preimage is absent or changed")
        record = _record_from_document(context_document)
        document = record.document
        if (document["schema_version"] != 3 or document["project_id"] != self.project_id
            or document["mission_id"] != mission_id):
            raise ValueError("initial scientific Context must be exact same-scope v3")
        context_object = TypedWorkspaceId(IdentityKind.CONTEXT, document["context_id"])
        after = direct_mission_scientific_context_successor(before.payload, context_id=context_object.value)
        creation_basis = "owner-initialized-scientific-context:" + _require_text(command_id, "command_id")
        semantic = {"mission_id": mission_id, "mission": after, "context": document,
                    "expected_store_cut": cut, "writer_owner": owner,
                    "writer_creation_basis": creation_basis}
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.MISSION, lease=None, command_id=command_id, actor=actor,
            command_kind=_SCIENTIFIC_INITIALIZATION_COMMAND_KIND, executive_epoch_id=None,
            request={"initialization": semantic}, semantic_payload=semantic,
            writes=(RevisionWrite(object_id=mission_object, payload=after, expected_revision=expected_head_revision),
                    RevisionWrite(object_id=context_object, payload=document, expected_revision=None)),
            target_head_key=mission_object.key, expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            dependency_heads=_scientific_context_dependency_heads(document, tuple(document["treatments"])),
            expected_canonical_authority_digest=expected_canonical_authority_digest,
            atomic_writer_claim_owner=owner, atomic_writer_claim_creation_basis=creation_basis,
        )

    def revise_mission_scientific_context(
        self, *, mission_id: str, expected_head_revision: int,
        expected_head_payload_digest: str, update: Mapping[str, Any],
        expected_store_cut: Mapping[str, Any], expected_canonical_authority_digest: str,
        principal_attestation: PrincipalAttestation, command_id: str, actor: str,
    ) -> CommandOutcome:
        """Revise only the bound scientific Context under stopped owner custody.

        Preparation reads exact retained preimages, never requires their current
        heads. The sole transaction checks exact replay first, then claims and
        releases the same quiesced principal atomically with one Context write.
        Mission binding/revision, Strategy and mathematical records do not change.
        """
        from .context_revision import (
            context_reference_key, prepare_scientific_context_update_for_scope,
            read_context_revision,
        )

        owner = stable_principal_owner_binding(principal_attestation)
        cut = _validated_mission_host_store_cut(expected_store_cut)
        if cut["canonical_authority_digest"] != expected_canonical_authority_digest:
            raise ValueError("scientific revision canonical authority differs from expected Store cut")
        mission_object = TypedWorkspaceId(IdentityKind.MISSION, mission_id)
        before = self.get_revision(RevisionRef(mission_object, expected_head_revision))
        if before is None or before.payload_digest != expected_head_payload_digest:
            raise StaleCommandError("scientific revision Mission preimage is absent or changed")
        if not isinstance(update, Mapping) or update.get("create") is not None:
            raise ValueError("stopped scientific revision requires a patch of the bound Context")
        kind, context_id, revision, digest = context_reference_key(update.get("expected_head"))
        if (kind != "context" or before.payload.get("scientific_context_id") != context_id
            or before.payload.get("project_id") != self.project_id or before.payload.get("mission_id") != mission_id):
            raise ValueError("scientific revision must preserve the exact Mission Context binding")
        previous = read_context_revision(self, context_id=context_id, revision=revision)
        prepared = prepare_scientific_context_update_for_scope(
            project_id=self.project_id, mission_id=mission_id, update=update, previous=previous,
        )
        if not prepared.changed:
            raise ValueError("stopped scientific revision has no semantic change; no writer was claimed")
        context_object = TypedWorkspaceId(IdentityKind.CONTEXT, context_id)
        dependencies = dict(prepared.dependency_heads)
        mission_head = (expected_head_revision, expected_head_payload_digest)
        if mission_object.key in dependencies and dependencies[mission_object.key] != mission_head:
            raise ValueError("scientific revision conflicts with its exact Mission preimage")
        dependencies[mission_object.key] = mission_head
        creation_basis = "owner-revised-scientific-context:" + _require_text(command_id, "command_id")
        semantic = {
            "mission_id": mission_id,
            "mission_reference": {"kind": "mission", "identity": mission_id,
                                  "revision": expected_head_revision, "payload_sha256": expected_head_payload_digest},
            "context": deep_thaw(prepared.record.document), "update": deep_thaw(update),
            "expected_store_cut": cut, "writer_owner": owner, "writer_creation_basis": creation_basis,
        }
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.CONTEXT, lease=None, command_id=command_id, actor=actor,
            command_kind=_SCIENTIFIC_REVISION_COMMAND_KIND, executive_epoch_id=None,
            request={"revision": semantic}, semantic_payload=semantic,
            writes=(RevisionWrite(object_id=context_object, payload=prepared.record.document, expected_revision=revision),),
            target_head_key=context_object.key, expected_target_revision=revision,
            expected_target_payload_digest=digest, dependency_heads=dependencies,
            expected_canonical_authority_digest=expected_canonical_authority_digest,
            atomic_writer_claim_owner=owner, atomic_writer_claim_creation_basis=creation_basis,
        )

    def bind_mission_scientific_context(
        self,
        *,
        mission_id: str,
        expected_head_revision: int,
        expected_head_payload_digest: str,
        context_id: str,
        expected_context_revision: int,
        expected_context_payload_digest: str,
        expected_canonical_authority_digest: str,
        lease: WriterLease,
        command_id: str,
        actor: str,
    ) -> CommandOutcome:
        """Append only an owner-selected Mission-to-scientific-Context binding.

        Preparation reads immutable supplied revisions, never current heads.
        The ordinary writer transaction authenticates replay before its atomic
        custody, canonical/Mission/Context currentness and no-active-Epoch checks.
        It does not create a Context or change Strategy/canonical mathematics.
        """
        from .context_revision import _record_from_document
        from .mission_owner import direct_mission_scientific_context_successor

        mission_id = _require_text(mission_id, "mission_id")
        for name, revision in (
            ("expected_head_revision", expected_head_revision),
            ("expected_context_revision", expected_context_revision),
        ):
            if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
                raise ValueError(f"{name} must be one positive exact revision")
        for name, digest in (
            ("expected_head_payload_digest", expected_head_payload_digest),
            ("expected_context_payload_digest", expected_context_payload_digest),
            ("expected_canonical_authority_digest", expected_canonical_authority_digest),
        ):
            if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                raise ValueError(f"{name} must be one lowercase SHA-256")
        object_id = TypedWorkspaceId(IdentityKind.MISSION, mission_id)
        before = self.get_revision(RevisionRef(object_id, expected_head_revision))
        if (
            before is None
            or before.payload_digest != expected_head_payload_digest
            or before.payload.get("mission_id") != mission_id
            or before.payload.get("project_id") != self.project_id
        ):
            raise StaleCommandError("scientific Context binding Mission preimage is absent or changed")
        payload = direct_mission_scientific_context_successor(before.payload, context_id=context_id)
        context_object = TypedWorkspaceId(IdentityKind.CONTEXT, context_id)
        target = self.get_revision(RevisionRef(context_object, expected_context_revision))
        if target is None or target.payload_digest != expected_context_payload_digest:
            raise StaleCommandError("scientific Context binding target preimage is absent or changed")
        context = _record_from_document(target.payload)
        if (
            context.document["schema_version"] != 3
            or context.document["project_id"] != self.project_id
            or context.document["mission_id"] != mission_id
            or context.document["context_id"] != context_id
            or context.digest_sha256 != expected_context_payload_digest
        ):
            raise WorkspaceIntegrityError("scientific Context binding target must be exact same-scope v3")
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.MISSION,
            lease=lease, command_id=command_id, actor=actor,
            command_kind="bind_mission_scientific_context",
            executive_epoch_id=None,
            request={
                "mission_id": mission_id,
                "semantic_payload_digest": canonical_payload(payload).sha256,
                "context_id": context_id,
                "expected_context_revision": expected_context_revision,
                "expected_context_payload_digest": expected_context_payload_digest,
            },
            semantic_payload=payload,
            writes=(RevisionWrite(
                object_id=object_id, payload=payload,
                expected_revision=expected_head_revision,
            ),),
            target_head_key=object_id.key,
            expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            dependency_heads={
                context_object.key: (expected_context_revision, expected_context_payload_digest),
            },
            expected_canonical_authority_digest=expected_canonical_authority_digest,
        )

    def migrate_mission_model_policy(
        self,
        *,
        mission_id: str,
        expected_head_revision: int,
        expected_head_payload_digest: str,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Append the sole stopped-owner Sol/ultra to Astra/ultra revision.

        Read the supplied immutable predecessor, not the current head, so an
        exact command replay reconstructs its original envelope even after
        later owner or Epoch work. Currentness and absence of an active Epoch
        are checked atomically by the existing writer transaction.
        """

        mission_id = _require_text(mission_id, "mission_id")
        if (
            isinstance(expected_head_revision, bool)
            or not isinstance(expected_head_revision, int)
            or expected_head_revision < 1
        ):
            raise ValueError("model migration requires one positive predecessor revision")
        object_id = TypedWorkspaceId(IdentityKind.MISSION, mission_id)
        before = self.get_revision(RevisionRef(object_id, expected_head_revision))
        if (
            before is None
            or before.payload_digest != expected_head_payload_digest
            or before.payload.get("mission_id") != mission_id
        ):
            raise StaleCommandError("model migration predecessor is absent or changed")
        payload = direct_mission_astra_successor(
            before.payload,
            preserve_historical_shape=self._owner_mission_replay_preserves_historical_shape(
                command_id=command_id, command_kind="migrate_mission_model_policy",
                object_id=object_id, expected_head_revision=expected_head_revision,
            ),
        )
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.MISSION,
            lease=lease,
            command_id=command_id,
            actor=actor,
            command_kind="migrate_mission_model_policy",
            executive_epoch_id=None,
            request={
                "mission_id": mission_id,
                "semantic_payload_digest": canonical_payload(payload).sha256,
            },
            semantic_payload=payload,
            writes=(
                RevisionWrite(
                    object_id=object_id,
                    payload=payload,
                    expected_revision=expected_head_revision,
                ),
            ),
            target_head_key=object_id.key,
            expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            expected_canonical_authority_digest=expected_canonical_authority_digest,
        )

    def reauthorize_mission(
        self,
        *,
        mission_id: str,
        expected_head_revision: int,
        expected_head_payload_digest: str,
        executive_epoch_id: str,
        root_thread_id: str,
        expected_terminal_event_sha256: str,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Append one explicit new grant after the exact incident fence and terminal.

        Reconstruct from immutable inputs so an exact replay returns its original
        result even after later migration, Epoch work, or another revocation.
        Eligibility and current writer authority are checked by the transaction.
        """
        mission_id = _require_text(mission_id, "mission_id")
        executive_epoch_id = _require_text(executive_epoch_id, "executive_epoch_id")
        root_thread_id = _require_text(root_thread_id, "root_thread_id")
        if (
            isinstance(expected_head_revision, bool)
            or not isinstance(expected_head_revision, int)
            or expected_head_revision < 1
        ):
            raise ValueError(
                "Mission reauthorization requires a positive predecessor revision"
            )
        if (
            not isinstance(expected_terminal_event_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", expected_terminal_event_sha256) is None
        ):
            raise ValueError(
                "Mission reauthorization terminal digest must be lowercase SHA-256"
            )
        object_id = TypedWorkspaceId(IdentityKind.MISSION, mission_id)
        before = self.get_revision(RevisionRef(object_id, expected_head_revision))
        if (
            before is None
            or before.payload_digest != expected_head_payload_digest
            or before.payload.get("mission_id") != mission_id
        ):
            raise StaleCommandError(
                "Mission reauthorization predecessor is absent or changed"
            )
        payload = direct_mission_reauthorization_successor(
            before.payload,
            preserve_historical_shape=self._owner_mission_replay_preserves_historical_shape(
                command_id=command_id, command_kind="reauthorize_mission_revision",
                object_id=object_id, expected_head_revision=expected_head_revision,
            ),
        )
        semantic = {
            "mission": payload,
            "executive_epoch_id": executive_epoch_id,
            "root_thread_id": root_thread_id,
            "terminal_event_sha256": expected_terminal_event_sha256,
        }
        return self._apply_successor_storage_command(
            family=RevisionCommandFamily.MISSION,
            lease=lease,
            command_id=command_id,
            actor=actor,
            command_kind="reauthorize_mission_revision",
            executive_epoch_id=None,
            request={
                "mission_id": mission_id,
                "semantic_payload_digest": canonical_payload(semantic).sha256,
            },
            semantic_payload=semantic,
            writes=(
                RevisionWrite(
                    object_id=object_id,
                    payload=payload,
                    expected_revision=expected_head_revision,
                ),
            ),
            target_head_key=object_id.key,
            expected_target_revision=expected_head_revision,
            expected_target_payload_digest=expected_head_payload_digest,
            expected_canonical_authority_digest=expected_canonical_authority_digest,
        )

