    def commit_formal_session_revision(
        self,
        *,
        executive_epoch_id: str,
        mission_id: str,
        session_id: str,
        payload: Mapping[str, Any],
        expected_head_revision: int | None,
        expected_head_payload_digest: str | None,
        dependency_heads: Mapping[str, tuple[int, str]] | None = None,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Commit one conditional formal Session without taking Attempt ownership."""

        from .formal_session import _validate_formal_session_store_payload

        try:
            validated_payload = _validate_formal_session_store_payload(
                payload,
                project_id=self.project_id,
                mission_id=mission_id,
                session_id=session_id,
            )
        except (TypeError, ValueError) as exc:
            raise WorkspaceIntegrityError(
                "formal Session payload is invalid at the Store boundary"
            ) from exc
        if expected_head_revision is None and validated_payload["lifecycle"] != "open":
            raise WorkspaceIntegrityError(
                "a new formal Session Store owner must begin open"
            )
        payload_digest = canonical_payload(validated_payload).sha256
        if expected_head_revision is not None:
            if expected_head_revision == 1:
                if (
                    validated_payload["lifecycle"] == "open"
                    and expected_head_payload_digest != payload_digest
                ):
                    raise WorkspaceIntegrityError(
                        "an open formal Session revision may only replay exact bytes"
                    )
            elif expected_head_revision == 2:
                if (
                    validated_payload["lifecycle"] != "terminal"
                    or expected_head_payload_digest != payload_digest
                ):
                    raise WorkspaceIntegrityError(
                        "a terminal formal Session revision may only replay exact bytes"
                    )
            else:
                raise WorkspaceIntegrityError(
                    "formal Session Store history is limited to open then terminal"
                )
        return self._commit_successor_direct_owner_revision(
            executive_epoch_id=executive_epoch_id,
            kind=IdentityKind.SESSION,
            mission_id=mission_id,
            identity=session_id,
            payload=validated_payload,
            expected_head_revision=expected_head_revision,
            expected_head_payload_digest=expected_head_payload_digest,
            dependency_heads=dependency_heads,
            lease=lease,
            command_id=command_id,
            actor=actor,
            expected_canonical_authority_digest=(expected_canonical_authority_digest),
        )

    def commit_candidate_revision(
        self,
        *,
        executive_epoch_id: str,
        mission_id: str,
        candidate_id: str,
        payload: Mapping[str, Any],
        expected_head_revision: int | None,
        expected_head_payload_digest: str | None,
        dependency_heads: Mapping[str, tuple[int, str]] | None = None,
        a1_requirement: Mapping[str, Any] | None = None,
        lease: WriterLease,
        command_id: str,
        actor: str,
        expected_canonical_authority_digest: str,
    ) -> CommandOutcome:
        """Commit one Candidate revision without a Mission aggregate transition."""

        from .candidate_revision import (
            candidate_a1_requirement as required_candidate_a1,
            validate_candidate_revision,
        )

        material = deep_thaw(payload)
        historical_replay = False
        if material.get("schema_version") == 3:
            # Historical bytes remain replayable only as the exact already
            # committed command. This does not admit another v3 write lane.
            with self._connection(read_only=True) as connection:
                result = connection.execute(
                    "SELECT project_commit_no FROM command_result WHERE command_id = ?",
                    (command_id,),
                ).fetchone()
                if result is not None:
                    journal = _validated_commit_envelope(
                        connection, project_id=self.project_id, commit_no=int(result["project_commit_no"]),
                    )
                    target = RevisionRef(
                        TypedWorkspaceId(IdentityKind.CANDIDATE, candidate_id),
                        1 if expected_head_revision is None else expected_head_revision + 1,
                    )
                    if journal is not None and journal.row["command_kind"] == "commit_candidate_revision" and journal.changed_head_references == frozenset({target.key}):
                        row = connection.execute(
                            "SELECT * FROM candidate_revision WHERE object_id = ? AND revision = ?",
                            (candidate_id, target.revision),
                        ).fetchone()
                        if row is not None and str(row["payload_digest"]) == canonical_payload(material).sha256:
                            origin = _require_historical_typed_revision_origin(
                                connection, project_id=self.project_id, object_id=target.object_id,
                                row=row, allow_legacy_fallback=True,
                            )
                            historical_replay = origin == int(result["project_commit_no"])
        if material.get("schema_version") != 4 and not historical_replay:
            raise WorkspaceIntegrityError(
                "current Candidate writes require Candidate-v4; Candidate-v2/v3 are "
                "historical read/recovery material only"
            )
        required_a1: Mapping[str, Any] | None = None
        validation = validate_candidate_revision(material)
        if not validation.ok:
            assert validation.failure is not None
            raise WorkspaceIntegrityError(
                "Candidate payload is invalid at the Store boundary: "
                f"{validation.failure.location}: {validation.failure.message}"
            )
        required_a1 = required_candidate_a1(material)
        if a1_requirement is not None:
            if (
                required_a1 is None
                or deep_thaw(a1_requirement)
                != dict(_SUCCESSOR_CANDIDATE_A1_REQUIREMENT)
                or deep_thaw(a1_requirement) != deep_thaw(required_a1)
            ):
                raise WorkspaceIntegrityError(
                    "Candidate A1 requirement is not the exact closed successor contract"
                )
        elif required_a1 is not None:
            raise WorkspaceIntegrityError(
                "purported-complete Candidate requires atomic preservation and OPEN A1"
            )

        auxiliary_writes: tuple[AuxiliaryWrite, ...] = ()
        evidence_head_advances: tuple[EvidenceHeadAdvance, ...] = ()
        if required_a1 is not None:
            candidate_digest = canonical_payload(material).sha256
            (
                auxiliary_writes,
                evidence_head_advances,
            ) = self._prepare_successor_candidate_a1_projection(
                candidate_id=candidate_id,
                candidate_payload=material,
                candidate_digest=candidate_digest,
                actor=actor,
                expected_canonical_authority_digest=(
                    expected_canonical_authority_digest
                ),
            )
        return self._commit_successor_direct_owner_revision(
            executive_epoch_id=executive_epoch_id,
            kind=IdentityKind.CANDIDATE,
            mission_id=mission_id,
            identity=candidate_id,
            payload=payload,
            expected_head_revision=expected_head_revision,
            expected_head_payload_digest=expected_head_payload_digest,
            dependency_heads=dependency_heads,
            lease=lease,
            command_id=command_id,
            actor=actor,
            expected_canonical_authority_digest=(expected_canonical_authority_digest),
            request_extension={
                "a1_requirement": (
                    None if required_a1 is None else deep_thaw(required_a1)
                )
            },
            auxiliary_writes=auxiliary_writes,
            evidence_head_advances=evidence_head_advances,
        )

