    def _successor_direct_owner_mapping(
        self,
        *,
        kind: IdentityKind,
        mission_id: str,
        identity: str,
        stored: StoredRevision,
        connection: sqlite3.Connection | None = None,
        owner_origin_commit: int | None = None,
    ) -> Mapping[str, Any]:
        _family, _command_kind, identity_field = _SUCCESSOR_DIRECT_OWNER_SPECS[kind]
        if canonical_payload(stored.payload).sha256 != stored.payload_digest:
            raise WorkspaceIntegrityError(
                f"{kind.value.title()} revision payload digest is corrupt"
            )
        if kind is IdentityKind.SESSION:
            if stored.payload.get("kind") != "formal_session":
                raise StaleCommandError(
                    f"Session {identity} is a legacy MissionBundle owner, not a formal Session"
                )
            if connection is None or owner_origin_commit is None:
                raise WorkspaceIntegrityError(
                    "formal Session read lost its exact Store snapshot or origin"
                )
            _require_formal_session_capture_dependency(
                connection,
                project_id=self.project_id,
                mission_id=mission_id,
                session_id=identity,
                document=stored.payload,
                owner_origin_commit=owner_origin_commit,
            )
        if stored.payload.get(identity_field) != identity:
            raise WorkspaceIntegrityError(
                f"{kind.value.title()} revision payload has another owner identity"
            )
        if stored.payload.get("mission_id") != mission_id:
            raise StaleCommandError(
                f"{kind.value.title()} {identity} is absent from Mission {mission_id}"
            )
        return deep_freeze(
            {
                identity_field: identity,
                "mission_id": mission_id,
                "revision": stored.reference.revision,
                "payload": stored.payload,
                "payload_digest": stored.payload_digest,
                "predecessor_revision": stored.predecessor_revision,
                "created_actor": stored.created_actor,
                "created_at": stored.created_at,
            }
        )

    def _read_successor_direct_owner_revision(
        self,
        *,
        kind: IdentityKind,
        mission_id: str,
        identity: str,
        revision: int | None,
    ) -> Mapping[str, Any]:
        _family, _command_kind, identity_field = _SUCCESSOR_DIRECT_OWNER_SPECS[kind]
        mission_id = _require_text(mission_id, "mission_id")
        identity = _require_text(identity, identity_field)
        object_id = TypedWorkspaceId(kind, identity)
        if kind is IdentityKind.SESSION:
            revision_table, _head_table = _REVISION_TABLES[kind]
            with self._connection(read_only=True) as connection:
                self._reject_retired_observer_workspace(
                    connection,
                    operation="formal Session revision reads",
                )
                if not connection.in_transaction:
                    connection.execute("BEGIN")
                row = (
                    _typed_head_from_connection(connection, object_id)
                    if revision is None
                    else connection.execute(
                        f"SELECT * FROM {revision_table} "
                        "WHERE object_id = ? AND revision = ?",
                        (identity, revision),
                    ).fetchone()
                )
                if row is None:
                    suffix = "" if revision is None else f"@{revision}"
                    raise StaleCommandError(
                        f"Session revision is absent: {identity}{suffix}"
                    )
                head = _typed_head_from_connection(connection, object_id)
                if head is not None and int(head["revision"]) < int(row["revision"]):
                    raise WorkspaceIntegrityError(
                        "formal Session revision lies beyond its current head"
                    )
                origin_commit = _require_historical_typed_revision_origin(
                    connection,
                    project_id=self.project_id,
                    object_id=object_id,
                    row=row,
                )
                return self._successor_direct_owner_mapping(
                    kind=kind,
                    mission_id=mission_id,
                    identity=identity,
                    stored=self._stored_revision(object_id, row),
                    connection=connection,
                    owner_origin_commit=origin_commit,
                )
        stored = (
            self.get_head(object_id)
            if revision is None
            else self.get_revision(RevisionRef(object_id, revision))
        )
        if stored is None:
            suffix = "" if revision is None else f"@{revision}"
            raise StaleCommandError(
                f"{kind.value.title()} revision is absent: {identity}{suffix}"
            )
        return self._successor_direct_owner_mapping(
            kind=kind,
            mission_id=mission_id,
            identity=identity,
            stored=stored,
        )

    def read_branch_revision(
        self,
        *,
        mission_id: str,
        branch_id: str,
        revision: int | None = None,
    ) -> Mapping[str, Any]:
        """Read one exact current or historical Branch revision."""

        return self._read_successor_direct_owner_revision(
            kind=IdentityKind.BRANCH,
            mission_id=mission_id,
            identity=branch_id,
            revision=revision,
        )

